// Заметки и боковая панель, в которой они открываются. Собирается build.py.
(function () {
const NOTES = {"«Каменная стена» и безразличие — как Розенфельд читает пессимизм Фрейда (Розенфельд, 1964)": "Розенфельд сводит фрейдовскую позицию к трём формулам: у страдающих нарциссическими неврозами нет способности к переносу или есть лишь недостаточные её остатки; их сопротивление — каменная стена, которую не перелезть; они отворачиваются от врача **не враждебно, а безразлично**.\n\nИ тут же констатирует: большинство аналитиков, действительно лечивших нарциссических пациентов, с этим не согласились — Вельдер (1925), Кларк (1933), Фромм-Райхман (1943, 1947), Бион (1962), он сам. А раз перенос есть главное средство любого аналитического исследования, то для понимания нарциссизма необходимо самым пристальным образом наблюдать поведение нарцисса именно в переносной ситуации.\n\nХод мысли стоит запомнить: не «Фрейд ошибся», а «то, что он описал как отсутствие, следует рассмотреть подробнее и увидеть в этом структуру».\n\n<p class=\"src\">Источник: Розенфельд, Психотические состояния (1965)<\/p>\n\n## Связанные заметки\n\n→ <a class=\"note\" data-note=\"Отсутствие переноса при нарциссических неврозах как причина неудачи терапии (Фрейд, 1916-17)\">Отсутствие переноса при нарциссических неврозах как причина неудачи терапии (Фрейд, 1916-17)<\/a>\n→ <a class=\"note\" data-note=\"Не отсутствие переноса, а трудность его распознать (Розенфельд, 1952)\">Не отсутствие переноса, а трудность его распознать (Розенфельд, 1952)<\/a>\n→ Различие невроза переноса и нарциссического невроза стоит снять (Кон и Стоун, у Розенфельда, 1964)", "Адгезивная идентификация как модель массовой идентификации с толпой (Гампель)": "<p class=\"src\">Источник: (К) Гампель, Групповая психология, общество и массы<\/p>\n\n## Тезис\n\nГампель напрямую соединяет два, до этого не связанных в базе, понятия: адгезивную идентификацию Эстер Бик (Адгезивная идентификация как защита от страха падения) и массовую психологию Ле Бона/Фрейда. Адгезивная идентификация — единичная, поверхностная, пустая форма идентификации: только кожа-к-коже, без глубины, без признания отдельного существования объекта, — порождающая цепляющуюся зависимость. Это, по Гампель, **в точности та же структура**, что описывает Ле Бон применительно к толпе, а Фрейд (1921) — применительно к орде: индивид в массе теряет собственные суждения точно так же, как в адгезивной идентификации теряется ощущение отдельности объекта; фигуры-лидеры принимаются абсолютно на веру — так же автоматически, как обычно принимают на веру намерения собственной руки.\n\n## Мост к проективной идентификации\n\nКоллапс такой (адгезивной/массовой) идентификации переживается как отвержение зависимости — чувство, что тебя отбросил объект-лидер. Именно здесь, по Гампель, виден вход в проективную идентификацию: нарциссическая идентификация размывается в путаницу, при которой нечто, принадлежащее субъекту, передаётся в объект, так что субъект теряет часть своей индивидуальности, а объект наделяется чуждой ему идентичностью. Тот же механизм независимо описывают Ле Бон применительно к толпе и Фрейд применительно к орде: эмоциональная близость и импульсивное поведение производны от проекции Я-идеала на лидера и идентификации с ним и друг с другом.\n\n## Значение\n\nЭто заполняет содержательный пробел между двумя ранее не связанными кластерами базы — примитивными защитами (Бик/Мельцер/Тастин, индивидуальная клиника) и массовой психологией (Ле Бон/Фрейд/Кернберг, социальный уровень): один и тот же структурный паттерн (двумерная, безглубинная связь с объектом) описывается на двух разных уровнях анализа.\n\n→ Адгезивная идентификация как защита от страха падения\n→ Фрейд — либидинозная конституция массы и Я-идеал в группе\n→ Групповая Проективная идентификация\n→ Радиоактивная идентификация (Гампель)", "Безымянный ужас — непринятое возвращается (Бион, 1962)": "Младенец не может сам переварить свои самые сильные состояния — страх умереть, распасться. Он проецирует их в мать. Мать в состоянии «мечтательности» (reverie) принимает эти проекции, перерабатывает их и возвращает младенцу в переносимом виде: страх становится чем-то, что можно чувствовать и о чём со временем можно думать.\n\nЕсли мать не может принять проекцию, происходит худшее: страх возвращается к младенцу, лишённый даже того смысла, который у него был. Бион называет это **безымянным ужасом** — ужасом без формы и имени, который нельзя ни помыслить, ни рассказать.\n\nТак нарушается сама способность думать: мышление, по Биону, вырастает из опыта, что невыносимое кто-то однажды выдержал вместо тебя.\n\nСвязано: <a class=\"note\" data-note=\"Связывание-контейнирование-мышление\">Связывание-контейнирование-мышление<\/a> · <a class=\"note\" data-note=\"Протопамять как непереваренный элемент — Ройтман и модель контейнер-контейнируемое у Биона\">Протопамять как непереваренный элемент — Ройтман и модель контейнер-контейнируемое у Биона<\/a> · <a class=\"note\" data-note=\"Экстремальные переносы — бета-экраны для активации нерецептивного аналитика (Ферро)\">Экстремальные переносы — бета-экраны для активации нерецептивного аналитика (Ферро)<\/a>", "В массе человек спускается на несколько ступеней по лестнице цивилизации (Фрейд, 1921, Групповая психология)": "<p class=\"src\">Источник: Групповая психология и анализ Я, Фрейд, 1921 (Глава II, «Описание массовой души у Лебона»)<\/p>\n\n**Тезис.** Ещё один важный пункт для оценки массового индивида: одной лишь принадлежностью к организованной массе человек спускается на несколько ступеней по лестнице цивилизации.\n\n**Аргументы.** В своей отдельности он, возможно, был образованным индивидом — в массе он варвар, то есть **существо влечения** (Triebwesen). Ему свойственны спонтанность, необузданность, дикость, но также энтузиазм и героизм первобытных существ. Особо Лебон останавливается на снижении интеллектуальной работы, которое отдельный человек испытывает от растворения в массе. Фрейд подкрепляет это двустишием Шиллера: каждый по отдельности сносно умён и рассудителен, но собранные вместе (in corpore) они тут же превращаются в дурака.\n\n**Вывод.** Утрата культурного слоя в массе — не риторическая фигура, а описание регрессии: масса возвращает индивида к более раннему, влечёнческому уровню душевной организации. Именно поэтому всё дальнейшее описание массовой души у Лебона без всякого труда ложится на психоаналитическое описание примитивных народов и детей — что Фрейд и делает в следующем шаге.\n\n→ Массовая душа как душа примитивных и детей (Фрейд, 1921, Групповая психология)", "Взаимная индукция аффекта в массе (Фрейд, 1921, Групповая психология)": "<p class=\"src\">Источник: Групповая психология и анализ Я, Фрейд, 1921 (Глава III, «Другие оценки коллективной душевной жизни»)<\/p>\n\n**Тезис.** Самый примечательный и вместе с тем важнейший феномен массообразования — вызываемое у каждого отдельного человека **повышение аффективности** (exaltation or intensification of emotion).\n\n**Аргументы.** Едва ли при других условиях аффекты людей вырастают до такой высоты, как это происходит в массе, — и притом для участников это наслаждение: столь безгранично отдаваться своим страстям и при этом растворяться в массе, теряя чувство своей индивидуальной отграниченности. Это захваченность индивидов Макдугалл объясняет названным им «принципом прямой индукции аффекта путём первобытного симпатического отклика» (principle of direct induction of emotion by way of the primitive sympathetic response), то есть уже известным нам чувственным заражением. Механизм таков:\n\nЭтот автоматический принудительный ход тем сильнее, чем у большего числа лиц одновременно заметен один и тот же аффект: тогда критика отдельного человека умолкает, и он соскальзывает в тот же аффект — но при этом повышает возбуждение тех, кто подействовал на него, и так аффективная нагрузка отдельных лиц возрастает через **взаимную индукцию**. Здесь несомненно действует нечто вроде принуждения делать то же, что другие, оставаться в согласии со многими. При этом более грубые и простые чувственные движения имеют больше шансов распространиться в массе таким образом.\n\n**Вывод.** Заражение перестаёт быть загадочным «излучением» и получает описываемый механизм — круговую взаимную индукцию, в которой каждый одновременно приёмник и усилитель. Отбор по грубости чувства объясняет, почему массы объединяются вокруг простейших аффектов, а не сложных.\n\n→ Масса снимает совесть — выигрыш от отмены торможений (Фрейд, 1921, Групповая психология)\n\n→ Двуязычный плут на службе двух господ — смех par ricochet (Фрейд, 1905, Остроумие) (заразительность аффекта: индукция в массе и заражающий смех)", "Гипноз жуткий — мана вождя и взгляд, которого нельзя вынести (Фрейд, 1921, Групповая психология)": "<p class=\"src\">Источник: Групповая психология и анализ Я, Фрейд, 1921 (Глава X, «Масса и первобытная орда»)<\/p>\n\n**Тезис.** От сведе́ния массы к первобытной орде Фрейд ждёт большего: она должна приблизить и то непонятое, таинственное в массообразовании, что скрывается за загадочными словами «гипноз» и «внушение». **В гипнозе есть нечто прямо жуткое — а характер жуткого указывает на нечто старое и хорошо знакомое, подпавшее вытеснению** (отсылка к «Жуткому», 1919).\n\n**Аргументы.** Вспомним, как гипноз вводится: гипнотизёр утверждает, что владеет таинственной силой, отнимающей у субъекта собственную волю, — или, что то же самое, субъект в это верит. Эта таинственная сила, в народе часто называемая ещё животным магнетизмом, **должна быть той же, что у первобытных считается источником табу, — той, что исходит от королей и вождей и делает опасным приближение к ним (мана)**. И как гипнотизёр приводит её в явление? Он предлагает человеку смотреть ему в глаза; он гипнотизирует типическим образом своим взглядом. Но именно вид вождя для первобытного опасен и невыносим — как позже вид божества для смертного. Ещё **Моисей** должен быть посредником между своим народом и Иеговой, поскольку народ не вынес бы вида Бога; а возвращаясь от присутствия Бога, он сияет лицом — часть «маны» перешла на него, как на посредника у первобытных.\n\n**Вывод.** Гипноз жуток именно потому, что он не нов: он оживляет древнейшую и вытесненную ситуацию — предстояние перед всемогущим отцом орды. Тем самым «внушение» перестаёт быть тайной силой и становится историческим осадком.\n\n→ Всемогущество мысли и формула жуткого как вытесненное-и-возвращающееся (Фрейд, 1919) (та работа 1919 г., на которую Фрейд здесь ссылается за понятием жуткого)\n→ Техника гипноза — перенос на гипнотизёра (Фрейд, 1921, Групповая психология)", "Гипноз как влюблённость при исключении сексуального удовлетворения (Фрейд, 1921, Групповая психология)": "<p class=\"src\">Источник: Групповая психология и анализ Я, Фрейд, 1921 (Глава VIII, «Влюблённость и гипноз»)<\/p>\n\n**Тезис.** От влюблённости до гипноза, очевидно, недалеко: **гипнотизёр встал на место Я-идеала**.\n\n**Аргументы.** Совпадения обоих состояний бросаются в глаза: та же смиренная покорность, уступчивость, некритичность к гипнотизёру, что и к любимому объекту; то же всасывание собственной инициативы. В гипнозе все отношения только отчётливее и усиленнее, так что целесообразнее было бы пояснять влюблённость через гипноз, а не наоборот. Гипнотизёр — единственный объект, никакой другой рядом с ним не замечается. То, что Я как во сне переживает требуемое и утверждаемое им, напоминает нам: среди функций Я-идеала мы упустили назвать ещё и **осуществление проверки реальности** (отсылка к «Метапсихологическому дополнению к теории сновидений», 1917). Неудивительно, что Я считает восприятие реальным, если психическая инстанция, обычно ведающая проверкой реальности, сама выступает за эту реальность. Полное отсутствие стремлений с незаторможенными сексуальными целями добавляет явлениям крайней чистоты: **гипнотическое отношение есть неограниченная влюблённая отдача при исключении сексуального удовлетворения**, тогда как при влюблённости оно лишь временно отодвинуто и остаётся в фоне как позднейшая возможность цели.\n\n**Вывод.** Гипноз — не аналогия влюблённости, а её очищенный от чувственности случай; и именно поэтому он даёт чистый препарат того отношения, которое связывает члена массы с вождём.\n\n→ Галлюцинация требует отключения проверки реальности (Фрейд, 1917) (та работа 1917 г., на которую Фрейд здесь ссылается за понятием проверки реальности)\n→ Гипноз есть массообразование вдвоём (Фрейд, 1921, Групповая психология)", "До-символические формы символизации": "По Руссийон, 2011\n\n**До-символические формы** — это первичные процессуальные формы психического, возникающие до репрезентации и символа. Они относятся к уровню **первичной психической материи**, не несут значения и не являются образом или мыслью, а выражают **форму процесса** (движение, трансформацию, изменение состояния) и склонны к повторению при отсутствии метаболизации.", "Жадность, зависть и благодарность (Кляйн, 1957)": "В поздней книге «Зависть и благодарность» Кляйн разводит два близких, но разных чувства.\n\n**Жадность** — неудержимое желание, превосходящее и потребности субъекта, и то, что объект может и хочет дать. Её цель — выскрести, высосать досуха, поглотить грудь целиком. Жадность действует через интроекцию: взять всё внутрь.\n\n**Зависть** — злость на то, что у другого есть что-то желанное и хорошее, и импульс отнять это или испортить. Она действует через проекцию: вложить в хороший объект плохое, чтобы он перестал быть хорошим.\n\nПротивоположность обоим — **благодарность**: способность принять хорошее, наслаждаться им и сохранить его внутри. Из благодарности вырастает щедрость — желание делиться полученным.\n\nСвязано: <a class=\"note\" data-note=\"Зависть в аналитическом процессе\">Зависть в аналитическом процессе<\/a> · <a class=\"note\" data-note=\"Частичный и целый объект — путь к депрессивной позиции (Кляйн)\">Частичный и целый объект — путь к депрессивной позиции (Кляйн)<\/a>", "Зависть в аналитическом процессе": "Зависть — сквозная тема клинических примеров Биона: пациент завидует не только конкретным качествам аналитика, но самой возможности пары (пациент-аналитик) создавать нечто ценное — понимание, облегчение, смысл.\n\n- В примере с «двумя облаками вероятности» пациент боится, что зависть и ненависть к способности аналитика понимать заставят его принять в себя хороший, понимающий объект лишь для того, чтобы разрушить и вытеснить его; это порождает чувство преследования со стороны уже разрушенного и изгнанного объекта.\n- В примере с «голубой дымкой» переживание понятости — потенциально положительная связь — встречается ненавистью и трансформируется в нечто враждебное и разрушительное, обесценивая саму связь между пациентом и аналитиком.\n- В примере с «куском железа» зависть направлена на союз пациента и аналитика как таковой — на то, что вместе они способны вести работу, приносящую облегчение; эта зависть приводит к омертвению самой аналитической пары.\n- Согласно Биону, если объект (аналитик) выдерживает проекции пациента, не разрушаясь, зависть не исчезает, а переключается на саму эту способность оставаться спокойным контейнером.\n\n<p class=\"src\">Источник: Бион, 1959<\/p>\n**Связанные заметки:** Зависть к пониманию, Деструктивность в ПА, Усиливающий тревогу объект", "Заражение и внушаемость по Лебону — гипноз без гипнотизёра (Фрейд, 1921, Групповая психология)": "<p class=\"src\">Источник: Групповая психология и анализ Я, Фрейд, 1921 (Глава II, «Описание массовой души у Лебона»)<\/p>\n\n**Тезис.** Третья, и притом важнейшая причина обусловливает у объединённых в массу индивидов особые свойства, прямо противоположные свойствам изолированного индивида, — Лебон называет её внушаемостью, следствием которой оказывается уже упомянутое заражение.\n\n**Аргументы.** Для понимания этого явления нужно вспомнить некоторые новые открытия физиологии: человека посредством различных процедур можно привести в такое состояние, что он, утратив всю свою сознательную личность, подчиняется всем внушениям того, кто лишил его сознания собственной личности, и совершает поступки, находящиеся в резчайшем противоречии с его характером и привычками. Тщательные наблюдения показывают, что индивид, некоторое время пребывающий в недрах активной массы, вскоре — то ли под воздействием исходящих от неё излучений, то ли по иной неизвестной причине — оказывается в особом состоянии, весьма близком к фасцинации, охватывающей загипнотизированного под влиянием гипнотизёра: сознательная личность полностью исчезает, воля и способность к различению отсутствуют, все чувства и мысли ориентированы в направлении, заданном гипнотизёром. Примерно так же обстоит дело и с состоянием индивида, принадлежащего психологической массе: он больше не сознаёт своих действий; как у загипнотизированного, у него одни способности упраздняются, тогда как другие достигают высшей степени силы; под влиянием внушения он с неодолимым порывом примется исполнять определённые действия — и этот порыв в массах ещё неодолимее, чем у загипнотизированного, потому что одинаковое для всех индивидов внушение возрастает через взаимность. Главные признаки индивида, находящегося в массе: исчезновение сознательной личности, преобладание бессознательной личности, ориентация мыслей и чувств в одном направлении через внушение и заражение, тенденция к немедленному осуществлению внушённых идей; индивид перестаёт быть самим собой, становится автоматом без воли. Фрейд намеренно приводит цитату так подробно, чтобы подтвердить: Лебон действительно объявляет состояние индивида в массе гипнотическим, а не просто сравнивает его с ним. Фрейд не намерен здесь спорить, но хочет подчеркнуть: две последние причины изменения индивида в массе — заражение и повышенная внушаемость — явно неоднородны, поскольку заражение само должно быть проявлением внушаемости; действия обоих моментов у Лебона тоже кажутся недостаточно чётко разграниченными. Возможно, лучше всего истолковать его слова так: заражение отнести к воздействию отдельных членов массы друг на друга, тогда как приравненные к гипнотическому влиянию явления внушения в массе указывают на другой источник. Но на какой именно? Здесь бросается в глаза чувствительная неполнота: одна из главных частей этого уподобления — лицо, заменяющее для массы гипнотизёра, — в изложении Лебона вовсе не упоминается.\n\n**Вывод.** Это — решающий момент всей книги: Фрейд находит именно тот пробел в теории Лебона, который сам и заполнит, — Лебон описывает массу как гипнотическое состояние, но не называет гипнотизёра; вся дальнейшая аргументация Фрейда будет строиться вокруг того, что этим недостающим «гипнотизёром» оказывается вождь, а связь с ним — либидинозная привязанность, а не абстрактное «внушение».\n\n→ <a class=\"note\" data-note=\"В массе человек спускается на несколько ступеней по лестнице цивилизации (Фрейд, 1921, Групповая психология)\">В массе человек спускается на несколько ступеней по лестнице цивилизации (Фрейд, 1921, Групповая психология)<\/a>\n→ Престиж как парализующая критику власть (Фрейд, 1921, Групповая психология) (тот же пробел, зафиксированный в конце главы)", "Игра и переходное пространство": "Руссийон, 2011\nВ статье Руссийон **прямо говорит об игре** как об одной из фундаментальных форм **первичной символизации**, наряду с работой сновидения. Игра описывается как процесс, в котором первичная психическая материя может быть трансформирована, представлена и переработана **до речи**, в формах сцен, образов и процессуальных конфигураций. Через игру становится возможной первая интеграция опыта, не сводимая ни к действию, ни к восприятию.\nПри этом **термин «переходное пространство» не используется**. Руссийон не вводит винникоттовскую концепцию напрямую. Однако логика переходного пространства **имплицитно присутствует**: он говорит о необходимости **присутствия объекта**, о функциях окружения, о **разделяемости опыта** и о том, что символизация возникает на пересечении субъекта и объекта, в зоне, где ещё не проведено чёткое различие между внутренним и внешним.\n\n→ Роль и функция творчества в аналитическом кабинете по Винникотту — та же связка игры и переходного пространства, но у самого Винникотта", "Идентификация амбивалентна с самого начала — её оральное происхождение (Фрейд, 1921, Групповая психология)": "<p class=\"src\">Источник: Групповая психология и анализ Я, Фрейд, 1921 (Глава VII, «Идентификация»)<\/p>\n\n**Тезис.** Идентификация **с самого начала амбивалентна**: она может обратиться как в выражение нежности, так и в желание устранения.\n\n**Аргументы.** Она ведёт себя как отпрыск первой, **оральной фазы организации либидо**, в которой желанный и ценимый объект включали в себя посредством еды и тем самым как таковой уничтожали. Каннибал, как известно, остаётся на этой точке зрения: **он любит своих врагов до съедения — и съедает только тех, кого любит** (Фрейд отсылает к «Трём очеркам по теории сексуальности» и к работе Абрахама о раннейшей прегенитальной ступени развития либидо, 1916).\n\n**Вывод.** Двойственность идентификации не порок и не позднейшее осложнение, а её структура: любить и поглотить (то есть уничтожить как отдельное существо) здесь одно и то же движение. Это объясняет и враждебный поворот отцовской идентификации в Эдиповом комплексе, и позднейшую жестокость Я к интроецированному объекту в меланхолии.\n\n→ <a class=\"note\" data-note=\"Прегенитальные организации — оральная (каннибалическая) и садистско-анальная фазы (Фрейд, 1905, Три очерка)\">Прегенитальные организации — оральная (каннибалическая) и садистско-анальная фазы (Фрейд, 1905, Три очерка)<\/a>\n→ Судьба отцовской идентификации — обращённый Эдипов комплекс (Фрейд, 1921, Групповая психология)", "Идентификация или влюблённость — объект на месте Я или Я-идеала (Фрейд, 1921, Групповая психология)": "<p class=\"src\">Источник: Групповая психология и анализ Я, Фрейд, 1921 (Глава VIII, «Влюблённость и гипноз»)<\/p>\n\n**Тезис.** Различие идентификации и влюблённости в её высших образованиях, которые называют фасцинацией, влюблённой зависимостью (Hörigkeit), сначала кажется простым — но при ближайшем рассмотрении сводится к одной точной альтернативе: **ставится ли объект на место Я или на место Я-идеала**.\n\n**Аргументы.** На первый взгляд: в первом случае Я **обогатилось** свойствами объекта, «интроецировало» его (выражение Ференци); во втором оно **обеднело**, отдалось объекту, поставило его на место своей важнейшей составной части. Но такое изображение выдаёт за противоположности то, что ими не является: экономически речь идёт не об обеднении или обогащении, ведь и крайнюю влюблённость можно описать как интроекцию объекта в Я. Быть может, ближе к существу другое различение: при идентификации объект **утрачен или оставлен** и затем вновь воздвигнут в Я, которое частично изменяется по образцу утраченного объекта; в другом случае объект **сохранён** и как таковой сверхнагружен со стороны Я и за счёт Я. Но и против этого возникает сомнение: твёрдо ли установлено, что идентификация предполагает отказ от нагрузки объекта, — не может ли быть идентификации при сохранённом объекте?\n\n**Вывод.** Прежде чем вдаваться в обсуждение этого щекотливого вопроса, брезжит понимание: существо дела схватывает именно последняя альтернатива — **на место Я или на место Я-идеала**. Этим различением Фрейд и будет пользоваться до конца книги.\n\n→ <a class=\"note\" data-note=\"Гипноз как влюблённость при исключении сексуального удовлетворения (Фрейд, 1921, Групповая психология)\">Гипноз как влюблённость при исключении сексуального удовлетворения (Фрейд, 1921, Групповая психология)<\/a>", "Интроекция и инкорпорация — работа символа против магии (Абрахам и Торок)": "Абрахам и Торок разводят два процесса, которые у Фрейда и Кляйн часто смешиваются.\n\n**Интроекция** (понятие Ференци) — медленное расширение и обогащение внутреннего мира через символ. Утрата открывает в психике зазор; интроекция связывает влечение, привязанное к утраченному объекту, всё более точными метафорами, так что его энергию можно вернуть, а образ объекта — усвоить. Это процесс: он меняет психику.\n\n**Инкорпорация** — фантазм. Она лишь изображает глубокое психическое изменение с помощью магии. Чтобы не пришлось «проглотить» утрату, мы воображаем, будто проглотили — или уже проглотили — само утраченное, как вещь (Abraham & Torok, 1994, с. 126). Она сохраняет психику неизменной и отрицает саму травму.\n\nОбе операции растут из ротовой полости: младенец сначала буквально получает молоко, потом крик и слово начинают замещать отсутствующую грудь — так интроекция отделяется от инкорпорации.\n\n<p class=\"src\">Источник: Абрахам и Торок, Скорбь или меланхолия — интроекция против инкорпорации (1972)<\/p>\n\n## Связанные заметки\n\n→ Деметафоризация и объективация — два приёма инкорпорации (Абрахам и Торок)\n→ Крипта — объект, погребённый заживо внутри Я (Абрахам и Торок)\n→ Траур содержит утешение — объект теперь во мне, и я не могу его потерять (Абрахам, 1924)\n→ Тень объекта, павшая на Я — идентификация вместо отказа от объекта (Фрейд, 1917)\n→ Идентификация - это взаимодействие проекции и интроекции", "Искусство выводит Эвридику из ада — сублимация меланхолии (Кристева)": "Искусство и литература у Кристевой основаны на преодолённой меланхолии: это символическая сублимация, в которой символическое занимает место утраченного материнского объекта. «Мёртвый Христос» Гольбейна показывает, что произведение основано на преодолённом страдании — на воскрешении субъекта в символическом. Нерваль в сонете «El Desdichado» пытается дать имя Вещи, которую оплакивает, и превращает травматический опыт в самостоятельный символический предмет — сонет (с. 162).\n\nПоэт, по её образу, выводит Эвридику из меланхолического ада и возвращает ей новое существование в своём тексте-песне (с. 160). Для этого, считает Кристева, меланхолия должна быть выражена через ритм, мелодию, аллитерацию, а не через однозначную «информацию».\n\n<p class=\"src\">Источник: Кристева, Чёрное солнце (1987)<\/p>\n\n## Связанные заметки\n\n→ Асимболия — меланхолия как болезнь языка (Кристева)\n→ Целительного эффекта можно достичь, помещая свои болезненные переживания в вымышленные или фантастические конструкции.\n→ Жуткое в художественном вымысле — иные правила, чем в реальном опыте (Фрейд, 1919)", "Искусство как примирение двух принципов — художник как окольный герой (Фрейд, 1911)": "<p class=\"src\">Источник: Два принципа психической деятельности, Фрейд, 1911<\/p>\n\n## Тезис\n\nИскусство особым образом примиряет оба принципа сразу — там, где религия просто откладывает удовлетворение на потом, а наука обменивает удовольствие на пользу, искусство совмещает и то и другое одновременно. Художник изначально — человек, отворачивающийся от реальности, потому что не может смириться с требованием отказа от удовлетворения влечений в том виде, в каком оно предъявляется вначале, и дающий в жизни фантазии полную волю своим эротическим и честолюбивым желаниям.\n\n## Путь обратно в реальность\n\nНо художник, в отличие от невротика (застревающего в мире фантазии) и в отличие от обычного мечтателя (чьи грёзы наяву так и остаются частными), находит путь возврата из мира фантазии обратно в реальность: благодаря особому дару он придаёт своим фантазиям новую форму реальности, и другие люди признают за ними оправдание — как за ценным отражением действительной жизни. Так определённым, окольным путём он действительно становится тем героем, королём, творцом, любимцем, каким желал быть, — не проходя пути реального изменения внешнего мира.\n\n## Условие возможности — разделяемое неудовлетворение\n\nНо достичь этого художник может лишь потому, что другие люди испытывают то же неудовлетворение отказом, требуемым реальностью, что и он сам, — и это неудовлетворение, порождённое вытеснением принципа удовольствия принципом реальности, само есть часть самой реальности. Иными словами: искусство работает не потому, что художник исключителен, а потому, что его конфликт (между желанием и реальностью) — универсальный конфликт, разделяемый всей аудиторией.\n\n## Значение\n\nЭто компактная, ранняя формула теории сублимации применительно именно к художественному творчеству — прямой предшественник линии, которую Фрейд продолжит в работах о Леонардо да Винчи (1910, написана незадолго до этого текста) и о поэте и фантазировании; также прямая параллель тезису самого этого эссе о фантазировании как легальном «заповеднике» принципа удовольствия — искусство здесь оказывается способом сделать этот частный заповедник общедоступным и социально ценным.\n\n→ Фантазирование как заповедник принципа удовольствия (Фрейд, 1911)\n→ Развитие идей Фрейда о творчестве\n→ Наука как отречение от принципа удовольствия (Фрейд, 1910, Выбор объекта)", "Искусство как репарация (Сегал, 1952)": "В «Психоаналитическом подходе к эстетике» Ханна Сегал связывает творчество с депрессивной позицией. Художник переживает, что его внутренний мир разрушен, любимые объекты утрачены или мертвы, — и воссоздаёт их в произведении. Творчество — это **репарация**: восстановление разрушенного.\n\nПоэтому подлинная красота, по Сегал, всегда содержит и уродливое: в произведении есть признание разрушения и смерти, а не только гармония. Зритель, отождествляясь с художником, заново проходит вместе с ним путь от разрушения к восстановлению — и в этом источник эстетического переживания.\n\nСвязано: <a class=\"note\" data-note=\"Сублимация — карта области (Фрейд)\">Сублимация — карта области (Фрейд)<\/a> · <a class=\"note\" data-note=\"Искусство выводит Эвридику из ада — сублимация меланхолии (Кристева)\">Искусство выводит Эвридику из ада — сублимация меланхолии (Кристева)<\/a> · <a class=\"note\" data-note=\"Луиза Буржуа — искусство как гарантия душевного здоровья\">Луиза Буржуа — искусство как гарантия душевного здоровья<\/a>", "Использование объекта — другой реален, если пережил разрушение (Винникотт, 1969)": "Винникотт различает **отношение к объекту** и **использование объекта**. В отношении объект — во многом пучок проекций субъекта, он остаётся внутри всемогущего контроля. Использовать объект можно, только если он стал внешним, реальным, отдельным.\n\nКак совершается этот переход? Парадоксально: через разрушение. Субъект разрушает объект — в фантазии, в ярости, в нападении, — а объект **выживает**: не погибает, не мстит, не отворачивается. Именно выживание выводит его за пределы всемогущества и делает настоящим. Винникотт даёт этому почти поэтическую формулу: «Привет, объект! Я тебя разрушил. Я тебя люблю. Ты ценен для меня, потому что пережил моё разрушение».\n\nДля клиники это значит: аналитик должен выжить в атаках пациента — не обрушиться и не ответить местью. Только тогда он перестаёт быть проекцией и становится тем, кого можно использовать.\n\nСвязано: <a class=\"note\" data-note=\"Холдинг и страх падения — Винникотт\">Холдинг и страх падения — Винникотт<\/a> · <a class=\"note\" data-note=\"частичные объекты\">частичные объекты<\/a> · <a class=\"note\" data-note=\"Страх распада — катастрофа, которая уже случилась (Винникотт, 1974)\">Страх распада — катастрофа, которая уже случилась (Винникотт, 1974)<\/a>", "Когда кажется, что переноса в работе нет — карта темы": "**Идея.** Есть узнаваемое клиническое переживание: сессии идут, а переноса будто нет. Пациент не обращается к аналитику, не сердится на него, не привязывается; аналитику скучно, внимание не держится, кажется, что ничего не происходит. Фрейд объяснял это устройством пациента: нет объект-либидо — нет переноса — аналитик бессилен. Почти все, кто после него работал с нарциссическими и психотическими пациентами, это объяснение оспорили, и каждый по-своему. Тема собирает их вместе — вместе с той единственной областью, где отсутствие переноса оказывается настоящим.\n\n**Как пользоваться картой.** Пять ответов на один вопрос идут по нарастанию: сначала спор с исходным диагнозом, потом четыре разных объяснения того, почему переноса не видно, потом граница, где его правда нет, и наконец случай, когда его малость — ценность, а не проблема.\n\n## 0. Исходная позиция, с которой спорят\n\n→ <a class=\"note\" data-note=\"Отсутствие переноса при нарциссических неврозах как причина неудачи терапии (Фрейд, 1916-17)\">Отсутствие переноса при нарциссических неврозах как причина неудачи терапии (Фрейд, 1916-17)<\/a> — пациенты отвергают врача не враждебно, а безразлично; механизм исцеления просто нельзя запустить\n→ <a class=\"note\" data-note=\"«Каменная стена» и безразличие — как Розенфельд читает пессимизм Фрейда (Розенфельд, 1964)\">«Каменная стена» и безразличие — как Розенфельд читает пессимизм Фрейда (Розенфельд, 1964)<\/a> — сводка фрейдовской позиции и констатация, что практики с ней не согласились\n→ Аутоэротическая фаза как основание тезиса о неспособности к переносу (Розенфельд, 1952) — теоретическая опора тезиса пережила собственное основание\n\n## 1. Перенос есть, но говорит на незнакомом языке (Розенфельд)\n\n→ <a class=\"note\" data-note=\"Не отсутствие переноса, а трудность его распознать (Розенфельд, 1952)\">Не отсутствие переноса, а трудность его распознать (Розенфельд, 1952)<\/a> — формула, задающая всю тему\n→ Уход шизофреника — защита от преследователей, а не аутоэротизм (Розенфельд, 1952)\n→ Отстранённость второй сессии оказалась проективной идентификацией (Розенфельд, 1952)\n→ Кажущееся аутоэротическое состояние скрывает интроекцию и проекцию разом (Розенфельд, 1952)\n→ <a class=\"note\" data-note=\"Смешение с объектом как самая примитивная форма объектного отношения (Розенфельд, 1952)\">Смешение с объектом как самая примитивная форма объектного отношения (Розенфельд, 1952)<\/a>\n→ Скорость, с какой выходит негативный перенос у острого больного (Розенфельд, 1952)\n→ Интерпретировать проективную идентификацию, чтобы пациент мог «забрать себя обратно» (Розенфельд, 1952)\n\n## 2. Перенос спрятан защитой от отдельности (Розенфельд о нарциссизме)\n\n→ Защита от осознания отдельности делает нарциссический перенос невидимым (Розенфельд, 1964) — ключевая заметка раздела\n→ <a class=\"note\" data-note=\"Нарциссическое отношение переживается обеими сторонами как идеальное (Розенфельд, 1964)\">Нарциссическое отношение переживается обеими сторонами как идеальное (Розенфельд, 1964)<\/a> — перенос замаскирован под благополучие\n→ Состояния, похожие на первичный нарциссизм, суть примитивные объектные отношения (Розенфельд, 1964)\n→ Различие невроза переноса и нарциссического невроза стоит снять (Кон и Стоун, у Розенфельда, 1964)\n→ Прогноз измеряется тем, насколько пациент признаёт отношение к аналитику (Розенфельд, 1964)\n\n## 3. Перенос не тянет внимание, потому что к аналитику не обращаются (Кохут)\n\n→ Периоды, когда «ничего не происходит» — работа нарциссического переноса (Ромашкевич о Кохуте) — точная формулировка самого переживания\n→ <a class=\"note\" data-note=\"Отсутствие объектного катексиса — почему внимание не удерживается (Кохут)\">Отсутствие объектного катексиса — почему внимание не удерживается (Кохут)<\/a> — механизм\n→ <a class=\"note\" data-note=\"Скука аналитика как главная опасность переноса-слияния и близнецового (Кохут)\">Скука аналитика как главная опасность переноса-слияния и близнецового (Кохут)<\/a>\n→ Зеркальный перенос удерживает внимание, слияние — нет (Кохут) — ощущение пустоты как грубая шкала глубины регресса\n→ Невнимательность здесь — свойство ситуации, а не контрперенос (Кохут)\n→ Когда невнимательность всё-таки становится контрпереносом (Кохут)\n→ Защитная скука отличается от настоящей (Кохут)\n→ Равномерно парящее внимание держится, пока конфликты аналитика не мешают восприимчивости (Кохут)\n→ Нарциссическая уязвимость аналитиков остаётся невыявленной (Кохут)\n\n**Что с этим делать:**\n→ Аналитику отведено скромное место — условие работы с зеркальным переносом (Кохут)\n→ Нарциссический перенос не интерпретируют — он лекарство, а не болезнь (Ромашкевич о Кохуте)\n→ Нарциссический перенос — единственная нить, и порвать её легко (Ромашкевич о Кохуте)\n\n## 4. Переноса не видно, потому что смотрят не туда (Ферро)\n\n→ <a class=\"note\" data-note=\"Шкала переноса «Меркалли» — нулевой уровень не есть отсутствие (Ферро)\">Шкала переноса «Меркалли» — нулевой уровень не есть отсутствие (Ферро)<\/a> — «отсутствие переноса в анализе невозможно»\n→ Оазис Валентины — как выглядит нулевой уровень (Ферро) — сессия из шести рисунков, где перенос весь в персонажах поля\n→ Уровни контрпереноса — от поля-рассказчика до разрыва сеттинга (Ферро)\n→ <a class=\"note\" data-note=\"Экстремальные переносы — бета-экраны для активации нерецептивного аналитика (Ферро)\">Экстремальные переносы — бета-экраны для активации нерецептивного аналитика (Ферро)<\/a> — противоположный край той же шкалы\n\n## 5. Переноса нет не у пациента, а в конфигурации ситуации\n\n→ Защитное избегание Фрейд принял за неспособность к переносу (Ромашкевич о Кохуте) — сеттинг, в котором нарциссическое просто не всплывает\n→ Аналитик может незаметно мешать установлению зеркального переноса (Кохут) — помеха, защищённая ссылкой на технику\n→ Две причины, по которым Анна Фрейд не ждала невроза переноса у ребёнка (у Змановской) — аналитик стал слишком чётко очерченной фигурой\n→ «Не» реляционной работы — без переноса, проекции и искажений (Дрозек и др.) — крайний случай: конструкт переноса убран из языка намеренно\n\n## 6. Дистанция как способ сохранить аналитика\n\n→ пациент защищает аналитика — зависимость выражается только через горечь и упрёк, потому что сближение считается разрушительным\n→ одна из причин желания избавиться от части Я с помощью проективной идентификации защита аналитика\n→ психотический перенос как частный случай проективной идентификации — аналитик не отдельный объект, а часть внутреннего мира\n→ Толстокожий и тонкокожий нарцисс (Розенфельд) — плотность защитного барьера как мера того, насколько мало будет видно\n\n## 7. Перенос, который восстанавливается только задним числом\n\n→ Нарциссический перенос возможно анализировать, если его слушать\n→ Пациент К — отстранённый жаргон как ширма\n→ Суть &quot;слушания слушания&quot; и Функции &quot;слушания слушания&quot;\n→ Наделение смыслом молчания\n→ Мертвая мать — Андре Грин — присутствие при психической отсутствующести; след остаётся в форме сессии, а не в её содержании\n\n## 8. Где отсутствие переноса настоящее\n\n→ <a class=\"note\" data-note=\"Область созидания — третий уровень психики без внешнего объекта (Балинт)\">Область созидания — третий уровень психики без внешнего объекта (Балинт)<\/a>\n→ <a class=\"note\" data-note=\"Нет внешнего объекта — нет переноса, и метод бессилен (Балинт)\">Нет внешнего объекта — нет переноса, и метод бессилен (Балинт)<\/a> — единственная в теме честная граница метода\n→ Отсутствием переноса объясняется и неразработанность психологии беременности (Балинт)\n→ <a class=\"note\" data-note=\"Протообъект — имя для того, что есть там, где объектов нет (Балинт)\">Протообъект — имя для того, что есть там, где объектов нет (Балинт)<\/a>\n\n## 9. Где малость переноса — ценность, а не проблема\n\n→ «Момент встречи» — редкий случай, когда переноса действительно минимум (Бостонская группа)\n\n## Спор, который стоит держать в голове\n\nСогласившись, что перенос есть, авторы немедленно расходятся в том, что с ним делать. Розенфельд интерпретирует найденное отношение, потому что только так пациент сможет «забрать себя обратно». Кохут в изложении Ромашкевича не интерпретирует вовсе: нарциссический перенос — лекарство, а не болезнь, и разрушать его нельзя. Штайнер в версии TFP ищет средний путь — аналитик-центрированную интерпретацию и выжидание момента, когда грандиозность сама даст трещину (Такт и время — аналитик-центрированная интерпретация с нарциссическими пациентами (Штайнер, TFP)). Ферро переносит вопрос в поле: интерпретировать нужно не отношение, а рассказ. А MBT-N вообще отказывается от слова.\n\n## Мосты к другим частям базы\n\n→ Перенос и Контрперенос — структурные заметки\n→ Проективная идентификация и Если перенос включает в себя все объектные отношения\n→ Аналитическое поле, Поле, Перенос и контрперенос в группе — поле vs таксономия\n→ Нарциссизм — нарциссический кластер базы, куда тема вливается целиком\n→ Диагностика через селфобъектный перенос — методологическая проблема (Афек) — критика диагностики по типу переноса\n→ Почему нейтральность не работает с нарциссом (Дрозек и др.)\n\n## Источники\n\n→ Розенфельд, Психотические состояния (1965)\n→ Кохут, Анализ самости (1971)\n→ Ферро, Избегание эмоций, проживание эмоций (2023)\n→ Балиндт, базис дефект\n→ Змановская, Современный психоанализ\n→ Бостонская группа, 2005 — процесс изменения", "Компульсия судьбы — навязчивое повторение болезненного паттерна у душевно здоровых людей (Фрейд, 1920)": "<p class=\"src\">Источник: По ту сторону принципа удовольствия, Фрейд, 1920<\/p>\n\n## Тезис\n\nТот же навязчивый, «демонический» по характеру паттерн, что наблюдается в переносе у пациентов, встречается и у людей, вовсе не проходящих анализ: у всех нас есть знакомые, чьи отношения с людьми имеют один и тот же роковой исход при разных лицах и обстоятельствах — благодетель, которого через некоторое время неизменно покидают в гневе облагодетельствованные им подопечные; мужчина, чьи дружбы неизменно заканчиваются предательством со стороны друга; человек, вновь и вновь возводящий другого в позицию высшего авторитета, а затем сам же его свергающий; женщина, последовательно похоронившая трёх мужей у смертного одра, каждый раз в роли неутомимой сиделки.\n\n## Литературная иллюстрация\n\nФрейд приводит историю **Танкреда и Клоринды** из «Освобождённого Иерусалима» Тассо: герой по ошибке убивает возлюбленную Клоринду, сражавшуюся в доспехах врага; позже, зайдя в волшебный лес и поразив мечом дерево, он вновь слышит из него голос раненой Клоринды — судьба заставляет его ранить возлюбленную дважды.\n\n## Значение\n\nЭта «**компульсия судьбы**» позволяет утверждать, что навязчивое повторение — нечто более первичное, элементарное и инстинктивное, чем вытесненный им принцип удовольствия: перед нами не невротический симптом в узком смысле, а общечеловеческий паттерн, обнажающий работу того же механизма, что и в игре Fort-Da и в сопротивлении переносу, — и именно универсальность этого паттерна (у здоровых, не только у больных) толкает Фрейда искать для него объяснение не в клинике, а в самой природе влечения как такового.\n\n→ Навязчивое повторение в переносе — принуждение повторять вместо воспоминания (Фрейд, 1920)\n→ Консервативная природа влечений — восстановление более раннего состояния (Фрейд, 1920)", "Ложное творение — перверсия как подделка творчества (Шассге-Смиргель, 1984)": "Жанин Шассге-Смиргель в книге «Творчество и перверсия» описывает перверсию как попытку **отменить различия** — между полами и между поколениями. В перверсном мире всё смешано и уравнено; она называет его «анальной вселенной», где разнородное перемалывается в однородную массу.\n\nПерверт не признаёт, что отцовский мир существует и что взрослым ещё нужно стать. Вместо этого он создаёт свой продукт и выдаёт его за идеальный — превосходящий отцовское творение. Это **подделка творчества**: идеализация собственной смеси вместо признания утраты и долгого пути сублимации.\n\nОтличить подлинное от поддельного можно по тому, сохраняются ли в произведении различия — и остаётся ли место для другого.\n\nСвязано: <a class=\"note\" data-note=\"Фетишизм — условие пола, детская фиксация и символическая связь (Фрейд, 1905, Три очерка)\">Фетишизм — условие пола, детская фиксация и символическая связь (Фрейд, 1905, Три очерка)<\/a> · <a class=\"note\" data-note=\"Сублимация — карта области (Фрейд)\">Сублимация — карта области (Фрейд)<\/a> · <a class=\"note\" data-note=\"Искусство как репарация (Сегал, 1952)\">Искусство как репарация (Сегал, 1952)<\/a>", "Луиза Буржуа — искусство как гарантия душевного здоровья": "Луиза Буржуа (1911–2010) — французско-американская художница и скульптор. Она выросла под Парижем в семье, которая занималась реставрацией старинных гобеленов. Отец годами жил в доме с любовницей — английской гувернанткой детей, и вся семья об этом знала. Эта детская рана стала одной из главных тем её работы на протяжении семи десятилетий.\n\nСамые известные её работы — серия «Клетки», замкнутые комнаты-инсталляции с предметами памяти, и гигантские пауки. Крупнейший из них, «Маман» (1999), посвящён матери: паук плетёт и чинит, как мать чинила гобелены, — он защищает, а не угрожает. В поздние годы Буржуа шила скульптуры из старой одежды и тканей.\n\nФраза «Искусство — гарантия душевного здоровья» (Art is a guaranty of sanity) написана на одной из её работ. Её путь — пример творчества, которое не разрушает материал, а **чинит**: превращает травму в форму, к которой может прикоснуться другой.\n\nСвязано: <a class=\"note\" data-note=\"Искусство как репарация (Сегал, 1952)\">Искусство как репарация (Сегал, 1952)<\/a> · <a class=\"note\" data-note=\"Писатель и фантазирование — эстетическая премия (Фрейд, 1908)\">Писатель и фантазирование — эстетическая премия (Фрейд, 1908)<\/a>", "Нарциссическое отношение переживается обеими сторонами как идеальное (Розенфельд, 1964)": "Клинически нарциссические объектные отношения **часто выглядят для аналитика и переживаются пациентом как очень хорошие, идеальные и желательные**. Это едва ли не главная ловушка темы: перенос не просто незаметен — он замаскирован под благополучие.\n\nРозенфельд приводит формы этой маскировки. Аналитик в снах и фантазиях предстаёт уборной или коленями: любое неприятное чувство или ощущение можно немедленно эвакуировать в него без всякой заботы о нём, а сам объект при этом обесценен, — и отношение к такому аналитику-уборной переживается как идеальное, потому что в сессии наступает облегчение. Пациент, притязающий владеть анализом как кормящей грудью, записывает на свой счёт все удачные интерпретации аналитика — и переживает это как совершенство, ведь так он чувствует себя хорошим и значительным. Иногда нарциссические пациенты рисуют картину взаимно удовлетворяющих идеальных отношений, где личности пациента и аналитика не различаются, — то самое океаническое чувство.\n\nВ тяжёлых случаях мы неизменно видим жёсткую защиту от всякого осознания психической реальности: любая тревога от конфликта между частями себя или между собой и реальностью немедленно эвакуируется. Тревога, от которой так защищаются, преимущественно параноидная — нарциссические объектные отношения происходят из самого раннего младенчества.\n\n<p class=\"src\">Источник: Розенфельд, Психотические состояния (1965)<\/p>\n\n## Связанные заметки\n\n→ Защита от осознания отдельности делает нарциссический перенос невидимым (Розенфельд, 1964)\n→ Прогноз измеряется тем, насколько пациент признаёт отношение к аналитику (Розенфельд, 1964)\n→ пациент защищает аналитика\n→ Клинический пример — Грейс, «терапевт-банкомат» (TFP)", "Не отсутствие переноса, а трудность его распознать (Розенфельд, 1952)": "До недавнего времени, пишет Розенфельд, аналитики не брались лечить шизофреников, полагая, что шизофреник не способен образовать перенос. Собственный опыт говорит ему иное: **мы имеем дело не с отсутствием переноса, а с трудной задачей распознать и проинтерпретировать шизофренические переносные феномены.**\n\nЭто перенос вопроса из одной области в другую. У Фрейда неудача терапии объясняется устройством пациента: нет объект-либидо — нет и переноса, и аналитик бессилен (см. <a class=\"note\" data-note=\"Отсутствие переноса при нарциссических неврозах как причина неудачи терапии (Фрейд, 1916-17)\">Отсутствие переноса при нарциссических неврозах как причина неудачи терапии (Фрейд, 1916-17)<\/a>). У Розенфельда та же клиническая картина становится вопросом восприимчивости и техники аналитика: перенос есть, но говорит на языке, которому аналитика не учили.\n\nЦель статьи заявлена в трёх пунктах: показать, что острый шизофренический пациент способен образовать и положительный, и отрицательный перенос; что эти феномены можно интерпретировать пациенту; и что его отклик на интерпретацию временами отчётливо заметен.\n\n<p class=\"src\">Источник: Розенфельд, Психотические состояния (1965)<\/p>\n\n## Связанные заметки\n\n→ <a class=\"note\" data-note=\"Отсутствие переноса при нарциссических неврозах как причина неудачи терапии (Фрейд, 1916-17)\">Отсутствие переноса при нарциссических неврозах как причина неудачи терапии (Фрейд, 1916-17)<\/a>\n→ <a class=\"note\" data-note=\"«Каменная стена» и безразличие — как Розенфельд читает пессимизм Фрейда (Розенфельд, 1964)\">«Каменная стена» и безразличие — как Розенфельд читает пессимизм Фрейда (Розенфельд, 1964)<\/a>\n→ психотический перенос как частный случай проективной идентификации\n→ <a class=\"note\" data-note=\"Когда кажется, что переноса в работе нет — карта темы\">Когда кажется, что переноса в работе нет — карта темы<\/a>", "Нет внешнего объекта — нет переноса, и метод бессилен (Балинт)": "Об области созидания известно очень мало, несмотря на многочисленные усилия. Очевидная причина: **внешних объектов там нет, следовательно, невозможны и отношения переноса. Там же, где нет переноса, наши аналитические методы оказываются бессильны** — и в выводах мы ограничены наблюдениями за субъектом, который эту область уже покинул.\n\nРаботать мы начинаем только тогда, когда на сцене появляется внешний объект: законченное произведение искусства, математический или философский тезис, выразимый словами инсайт, — или болезнь, дошедшая до той стадии, когда человек может кому-то пожаловаться на самочувствие.\n\nЭто единственная позиция в теме, где отсутствие переноса не кажущееся, а настоящее, — и потому она задаёт границу. Балинт не говорит «перенос спрятан, ищите лучше», он говорит: здесь его нет, и инструмент сюда не достаёт. Проверять «кажется или нет» стоит именно этим вопросом: есть ли на сцене внешний объект.\n\n<p class=\"src\">Источник: Балиндт, базис дефект<\/p>\n\n## Связанные заметки\n\n→ <a class=\"note\" data-note=\"Область созидания — третий уровень психики без внешнего объекта (Балинт)\">Область созидания — третий уровень психики без внешнего объекта (Балинт)<\/a>\n→ Отсутствием переноса объясняется и неразработанность психологии беременности (Балинт)\n→ <a class=\"note\" data-note=\"Протообъект — имя для того, что есть там, где объектов нет (Балинт)\">Протообъект — имя для того, что есть там, где объектов нет (Балинт)<\/a>\n→ Самая важная терапевтическая задача по Балиндту", "Область созидания — третий уровень психики без внешнего объекта (Балинт)": "Кроме области эдипова конфликта и области базисного дефекта Балинт называет третью область психики — **область созидания.**\n\nРазличаются они устройством отношений. Область эдипова конфликта характеризуется взаимодействием между субъектом и минимум двумя отличными от него объектами. Область базисного дефекта — весьма специфическими отношениями, разворачивающимися исключительно между двумя персонами. В области созидания **внешний объект отсутствует**: субъект предоставлен самому себе, и главная его забота — сотворить нечто вне себя самого. То, что должно быть создано, может быть объектом, но не обязательно им является.\n\nСюда Балинт относит не только художественное творчество, самый яркий и часто упоминаемый пример, но и занятия математикой и философией, постижение и понимание чего-то или кого-то, — а также два чрезвычайно важных феномена: **ранние фазы физического или психического заболевания и спонтанное выздоровление.**\n\n<p class=\"src\">Источник: Балиндт, базис дефект<\/p>\n\n## Связанные заметки\n\n→ <a class=\"note\" data-note=\"Нет внешнего объекта — нет переноса, и метод бессилен (Балинт)\">Нет внешнего объекта — нет переноса, и метод бессилен (Балинт)<\/a>\n→ <a class=\"note\" data-note=\"Протообъект — имя для того, что есть там, где объектов нет (Балинт)\">Протообъект — имя для того, что есть там, где объектов нет (Балинт)<\/a>\n→ Обектные отношения Балиндт\n→ <a class=\"note\" data-note=\"Когда кажется, что переноса в работе нет — карта темы\">Когда кажется, что переноса в работе нет — карта темы<\/a>", "Обонятельное влечение и вытеснение нюха — гипотеза о цене культуры (Фрейд, 1909, Человек-Крыса)": "<p class=\"src\">Источник: Человек-Крыса, Фрейд, 1909<\/p>\n\nВ последнем замечании о влечениях при неврозе навязчивости Фрейд отмечает, что пациент оказался ещё и «нюхачом»: по его собственным словам, в детстве он, подобно собаке, узнавал каждого человека по запаху, и обонятельные восприятия и сегодня говорили ему больше, чем другим людям; нечто подобное Фрейд наблюдал и у других невротиков, навязчивых больных и истериков, и научился учитывать роль угасшего с детства обонятельного наслаждения в генезе неврозов. В самой общей форме он ставит вопрос: не вносит ли органическое вытеснение обонятельного наслаждения, неизбежно возникшее вместе с распрямлением человека и отдалением от земли, свой вклад в предрасположенность культурного человека к неврозу? Отсюда открылось бы понимание того, почему именно сексуальная жизнь при росте культуры вынуждена приносить жертвы вытеснению — учитывая давно известную тесную связь полового влечения с функцией органа обоняния у животных.\n\n→ Техники защиты навязчивой идеи — искажение, интервал, обобщение, двусмысленность (Фрейд, 1909, Человек-Крыса)\n→ Финальный образ трёх личностей пациента (Фрейд, 1909, Человек-Крыса)", "Обретение объекта как повторное обретение — грудь матери как прототип всякой любви (Фрейд, 1905, Три очерка)": "<p class=\"src\">Источник: Три очерка, Фрейд, 1905<\/p>\n\n## Тезис\n\nПока самые ранние сексуальные удовлетворения ребёнка ещё связаны с приёмом пищи, сексуальное влечение имеет объект вне собственного тела — материнскую грудь. Оно теряет этот объект позже — как раз в тот момент, когда ребёнок оказывается способен составить целостное представление о лице, которому принадлежит орган, доставляющий удовлетворение (то есть о матери как отдельном человеке). После этого влечение регулярно становится аутоэротичным, и лишь после преодоления латентного периода происходит возврат к первоначальному отношению.\n\n## Формула\n\nНеспроста сосание груди становится образцом («моделью») для каждой позднейшей любовной связи. **«Нахождение объекта на самом деле есть его повторное обретение»** (the object-finding is really a re-finding) — вся дальнейшая любовная жизнь человека структурирована как серия попыток вернуться к утраченному первому объекту, хотя бы приблизительно.\n\n## Продолжение — привязанность к воспитателям\n\nДаже после отделения сексуальной активности от приёма пищи от этого первого и важнейшего из всех сексуальных отношений остаётся значительная доля, подготавливающая выбор объекта и помогающая восстановить утраченное счастье. На протяжении латентного периода ребёнок учится любить других людей, помогающих ему в его беспомощности и удовлетворяющих его нужды, — по модели и как продолжение его инфантильных отношений с кормилицей/матерью.\n\n## Значение\n\nЭта формула — один из самых цитируемых и влиятельных афоризмов всего корпуса Фрейда: она задаёт саму логику последующей теории объектных отношений (выбор партнёра во взрослой жизни как повторение, а не изобретение с нуля) и напрямую предвосхищает клинические описания более поздних авторов о переносе как оживлении инфантильного отношения к первичному объекту.\n\n→ Два потока выбора объекта — нежный и чувственный, разделённые латентным периодом (Фрейд, 1905, Три очерка)\n→ Инцестуозный барьер и детский страх как сепарационная тревога (Фрейд, 1905, Три очерка)\n\n→ Нахождение объекта — на самом деле повторное нахождение материнской груди (Фрейд, 1905, Три очерка)\n\n*Краткая версия темы; подробный разбор — по ссылкам выше.*\n→ Инцестуозный соблазн в отношениях тёщи и зятя (Фрейд, 1913)\n→ Выбор объекта по типу отца и перенос материнской амбивалентности на мужа (Фрейд, 1933)", "Органическое вытеснение — прямохождение и упадок обоняния (Фрейд, 1930)": "<p class=\"src\">Источник: Недовольство культурой, Фрейд, 1930<\/p>\n\n## Тезис\n\nВ обширных примечаниях к главе IV Фрейд выдвигает спекулятивную гипотезу: возможно, не только культурное давление, но и нечто в самой природе сексуальной функции отказывает нам в полном удовлетворении. Отправная точка — переход человека к прямохождению: он понизил значение обонятельных раздражителей (некогда возбуждавших мужчину в связи с менструальным циклом женщины) в пользу зрительных, действующих постоянно, а не с перерывами; гениталии, прежде скрытые, стали видимыми и потребовали защиты, породив тем самым чувство стыда. «Табу менструации» коренится, по этой гипотезе, именно в этом «органическом вытеснении», барьере против пройденной фазы развития.\n\n## Бисексуальность и амбивалентность\n\nДополнительные соображения: человек — животное с несомненно бисексуальной предрасположенностью, и оба пола часто нуждаются в удовлетворении на разных объектах, что порождает внутренний конфликт влечений; кроме того, эротическая связь нередко сопряжена с прямой агрессивностью сверх изначально присущих ей садистских компонентов (иллюстрация — крестьянка, жаловавшаяся, что муж разлюбил её, потому что не бил уже неделю).\n\n## Итог гипотезы\n\nСамое далеко идущее предположение: не только анальный эротизм, но и вся сексуальность в целом оказывается под угрозой того же «органического вытеснения», последовавшего за переходом к прямохождению и понижением ценности обоняния, — так что с этого момента половая функция сопровождается необъяснимым до конца сопротивлением, препятствующим полному удовлетворению и вынуждающим её искать выход в сублимации и смещениях либидо. Фрейд ссылается на близкую по духу идею Блейлера о «сексуальном сопротивлении» и подчёркивает, что эти соображения остаются недоказанными возможностями, а не научно установленными фактами.\n\n## Значение\n\nРадикальное расширение тезиса о сексуальном лишении: если верно, что часть сексуальной неудовлетворённости человека имеет органические, а не только культурные корни, то полное «освобождение» сексуальности реформой воспитания принципиально не могло бы устранить весь источник недовольства — важная оговорка, ограничивающая социально-реформаторские выводы, которые можно было бы сделать из анализа сексуального лишения.\n\n→ Эскалация сексуальных запретов культуры (Фрейд, 1930)\n→ Анатомия есть судьба — два источника неполноты сексуального удовлетворения (Фрейд, 1912)", "От тотемической трапезы к христианскому причастию — эволюция жертвоприношения (Фрейд, 1913)": "<p class=\"src\">Источник: Тотем и табу, Фрейд, 1913<\/p>\n\n## Возврат человеческого облика отцу-жертве\n\nКогда заместитель отца в культе вновь обретает человеческий облик (вместо тотемного животного), возникает человеческое жертвоприношение: Фрэзер описывает царей-чужестранцев, ритуально приносимых в жертву как боги на положенных празднествах. Далее возникают юные боги-сыновья (Аттис, Адонис, Таммуз) — духи растительности, любовники материнских божеств, совершающие символический инцест с матерью-землёй в пику отцу; вина за это не облегчается, а выражается в мифах об их наказании — кастрации или гибели от руки священного животного отцовского божества (Адониса убивает вепрь Афродиты; Аттис, любовник Кибелы, гибнет от кастрации).\n\n## Кульминация — жертва Христа\n\nКульминация этой линии — Христос, который искупает первородный грех перед Отцом собственной жертвенной смертью. Учение о первородном грехе орфического происхождения: люди — потомки титанов, убивших и растерзавших юного Диониса-Загрея, и несут на себе вину этого преступления. Логика возмездия требует: убийство искупается только жертвой другой жизни; самопожертвование указывает на кровную вину — а значит, если жертва собственной жизнью примиряет с Богом-Отцом, искупаемым грехом могло быть только убийство отца.\n\n## Причастие — новое устранение отца\n\nВ христианском учении человечество наиболее полно признаёт вину первобытного деяния именно потому, что находит для неё самое полное искупление — жертвенную смерть сына. Примирение с отцом тем более полно, что сопровождается полным отказом от женщины, из-за которой человечество некогда восстало против отца. Но психологическая закономерность амбивалентности требует своего: в том же самом действии, что предлагает отцу величайшее возможное искупление, сын достигает и цели своих желаний против отца — становится богом сам, рядом с отцом или вместо него. Религия сына сменяет религию отца. Знаком этой замены служит возрождение древней тотемической трапезы в форме причастия, в котором братия вкушает уже не плоть и кровь отца, а плоть и кровь сына, отождествляясь с ним и становясь тем самым священной. По существу христианское причастие — новое устранение отца, повторение искупаемого преступления. Отсюда справедлива формула Фрэзера: «христианское причастие впитало в себя таинство, несомненно куда более древнее, чем само христианство».\n\n## Значение\n\nЭто прослеживает единую нить (тотемическая трапеза → жертвоприношение животного → человеческое жертвоприношение бога-царя → жертва богов-сыновей → жертва Христа → причастие) как последовательные трансформации одного и того же неразрешённого конфликта — а не как случайный набор религиозных обычаев разных эпох.\n\n→ Отец представлен дважды в сцене жертвоприношения — бог и жертвенное животное (Фрейд, 1913)\n→ Трагический герой как повторение первобытного отца — инверсия исторической сцены (Фрейд, 1913)", "Отсутствие объектного катексиса — почему внимание не удерживается (Кохут)": "Кохут объясняет скуку через метапсихологию внимания. Подлинная бдительность при долгом наблюдении держится только на глубокой вовлечённости наблюдателя. Направленные на объект стремления, как правило, вызывают эмоциональную реакцию у того, на кого направлены, — поэтому даже когда аналитик в полной растерянности относительно смысла сказанного, наблюдение за объектно-инстинктивными проявлениями переноса обычно не наводит на него скуку.\n\nМатериал же нарциссических пациентов не затрагивает бессознательной настроенности аналитика так, как ассоциации при неврозах переноса. **Когда грандиозная самость активируется в форме слияния с психическими репрезентантами аналитика, объектного катексиса не существует вовсе**, и привязанность пациента носит специфически архаичный характер.\n\nВнимание при этом ещё активируется когнитивной задачей — понять загадочные проявления архаичных нарциссических отношений, — и аналитик может чувствовать себя угнетённым очевидными, хотя и невысказанными требованиями, которые с точки зрения цели слияния равносильны полному порабощению. Но отсутствия объектно-инстинктивных катексисов это не отменяет, и потому долго оставаться по-настоящему внимательным ему часто не удаётся.\n\n<p class=\"src\">Источник: Кохут, Анализ самости (1971)<\/p>\n\n## Связанные заметки\n\n→ <a class=\"note\" data-note=\"Скука аналитика как главная опасность переноса-слияния и близнецового (Кохут)\">Скука аналитика как главная опасность переноса-слияния и близнецового (Кохут)<\/a>\n→ Зеркальный перенос удерживает внимание, слияние — нет (Кохут)\n→ Невнимательность здесь — свойство ситуации, а не контрперенос (Кохут)\n→ <a class=\"note\" data-note=\"селфобъект и зеркальный перенос у Кохута\">селфобъект и зеркальный перенос у Кохута<\/a>", "Отсутствие переноса при нарциссических неврозах как причина неудачи терапии (Фрейд, 1916-17)": "<p class=\"src\">Источник: Вводные лекции, Фрейд, 1916-17 (лекция 27)<\/p>\n\n## Разгадка\n\nПочему терапия неизменно терпит неудачу при паранойе, меланхолии и dementia praecox, хотя причинные условия там в принципе схожи с неврозами переноса (тот же исходный конфликт Я и либидо, то же вытеснение, доступное реконструкции)? Наблюдение даёт простой ответ: у пациентов, страдающих нарциссическими неврозами, способность к **переносу отсутствует или крайне скудна**. Они отвергают врача не враждебно (что тоже было бы формой переноса), а **безразлично** — его слова оставляют их холодными, не производят впечатления.\n\n## Механизм неудачи\n\nРаз способности к переносу нет, механизм исцеления, работающий в других случаях (оживление патогенного конфликта через отношение к врачу и преодоление сопротивления с опорой на это отношение), просто не может быть запущен. Пациенты остаются такими, какие есть; аналитик перед ними бессилен.\n\n## Подтверждение исходной гипотезы\n\nПоведение этих пациентов при попытках терапии прямо подтверждает более раннее клиническое предположение (лекция 26): их либидинозная занятость объектов должна была быть оставлена, объект-либидо превратилось в Я-либидо (нарциссизм). Именно на основании этой особенности их и отделили от первой группы неврозов (истерии, тревоги, невроза навязчивости) ещё до всякой попытки лечения — и поведение при терапии лишь верифицирует это разделение задним числом.\n\n## Значение\n\nЗамыкающий аргумент всей теории нарциссизма: клиническая неудача терапии — не досадный пробел метода, а прямое, ожидаемое следствие теоретической модели (отсутствие объект-либидо → отсутствие переноса → невозможность оживить и разрешить конфликт через отношения с врачом).\n\n→ Вера пациента и предел влияния анализа — нарциссизм как граница (Фрейд, 1916-17)\n→ Нарциссизм и Я-либидо — открытие Абрахама о dementia praecox (Фрейд, 1916-17)\n→ Лечение любовью как обходной путь к утраченному нарциссизму невротика (Фрейд, 1914)\n\n### Продолжение темы: кажущееся отсутствие переноса\n\n→ <a class=\"note\" data-note=\"Не отсутствие переноса, а трудность его распознать (Розенфельд, 1952)\">Не отсутствие переноса, а трудность его распознать (Розенфельд, 1952)<\/a>\n→ <a class=\"note\" data-note=\"«Каменная стена» и безразличие — как Розенфельд читает пессимизм Фрейда (Розенфельд, 1964)\">«Каменная стена» и безразличие — как Розенфельд читает пессимизм Фрейда (Розенфельд, 1964)<\/a>\n→ Защитное избегание Фрейд принял за неспособность к переносу (Ромашкевич о Кохуте)\n→ <a class=\"note\" data-note=\"Когда кажется, что переноса в работе нет — карта темы\">Когда кажется, что переноса в работе нет — карта темы<\/a>", "Первичная и вторичная символизация": "Пара понятий из работы Рене Руссийона «Работа символизации» (Руссийон, 2011), описывающая два последовательных уровня символизации.\n\n**Первичная символизация** — уровень и процесс, через который первичная психическая материя (мнестические следы, Мнестические следы) трансформируется в **репрезентации вещей** (репрезентант-вещь, репрезентант-действие, репрезентант трансформации). Носит сенсорно-моторный характер и разворачивается ещё до слов — через формальные означающие (Анзье), пиктограммы (Оланье), проторепрезентации (Пинол-Дурье). Не солипсистический процесс: требует присутствия объекта и участия окружения. Модельные формы — работа сновидения (Символизация через сновидения) и работа игры (Символизация через игру).\n\n**Вторичная символизация** — перевод репрезентаций вещей в аппарат устной речи, то есть в **репрезентации слов**. Не сводится к простому «переводу в слова»: вовлекает лексику, синтаксис, повествовательную организацию, прагматику, а также телесное измерение речи (голос, интонацию, просодию). Обеспечивает рефлексивное становление психических процессов и вписывает содержание в контекст истории и отношений.\n\nВместе эти два уровня образуют цепочку: мнестические следы → метаболизация → первичная символизация (вещь) → вторичная символизация (слово) → субъективация — движение от Оно (место записи опыта) к Я (место владения опытом).\n\n→ Различия первичной и вторичной символизации — та же пара сжато, с опорой на Пайнса\n→ Типы репрезентации по Руссийону\n→ Условия символизации\n\n<p class=\"src\">Источник: Руссийон, 2011, Конспект по Руссийону<\/p>\n**Связанные заметки:** Символизация (полный разбор ветки Руссийона), Первичная психическая материя", "Перенос — промежуточное царство между болезнью и жизнью (Фрейд, 1914)": "В статье «Воспоминание, повторение и переработка» Фрейд описывает поворот в технике: пациент часто не **вспоминает** забытое, а **повторяет** его — в поступках, в жизни и прежде всего в отношении к аналитику. Это навязчивое повторение, и оно не прекращается от одного запрета.\n\nФрейд предлагает не бороться с повторением, а дать ему место. Перенос становится «игровой площадкой», где навязчивому повторению позволено развернуться почти свободно. Так перенос создаёт **промежуточное царство между болезнью и жизнью**, через которое и совершается переход от одной к другой. Обычный невроз заменяется «неврозом переноса» — искусственной болезнью, доступной работе.\n\nГлавное слово статьи — **переработка**: долгое, терпеливое прохождение через сопротивления, которое нельзя ускорить ни объяснением, ни волевым усилием.\n\nСвязано: <a class=\"note\" data-note=\"Компульсия судьбы — навязчивое повторение болезненного паттерна у душевно здоровых людей (Фрейд, 1920)\">Компульсия судьбы — навязчивое повторение болезненного паттерна у душевно здоровых людей (Фрейд, 1920)<\/a> · <a class=\"note\" data-note=\"Игра и переходное пространство\">Игра и переходное пространство<\/a> · <a class=\"note\" data-note=\"Призраки становятся предками (Лёвальд, 1960)\">Призраки становятся предками (Лёвальд, 1960)<\/a>", "Писатель и фантазирование — эстетическая премия (Фрейд, 1908)": "Фрейд сравнивает писателя с играющим ребёнком: тот тоже всерьёз строит собственный мир и при этом хорошо отличает его от действительности. Взрослый перестаёт играть, но не отказывается от удовольствия — он начинает фантазировать и стыдится своих грёз, потому что они детские или запретные.\n\nПисатель делает с тем же материалом то, что не удаётся никому из нас: рассказывает свои грёзы так, что они доставляют удовольствие. Его техника двояка. Он смягчает эгоистический характер грёзы изменениями и маскировкой. И он подкупает нас чисто формальным, эстетическим удовольствием — «премией-соблазном», предварительным удовольствием, которое открывает путь к удовольствию более глубокому.\n\nЭто глубокое удовольствие в том, что произведение позволяет нам **наслаждаться собственными фантазиями без упрёков и стыда**. Искусство не навязывает зрителю чужую грёзу, а возвращает его к своей.\n\nСвязано: <a class=\"note\" data-note=\"Искусство как примирение двух принципов — художник как окольный герой (Фрейд, 1911)\">Искусство как примирение двух принципов — художник как окольный герой (Фрейд, 1911)<\/a> · <a class=\"note\" data-note=\"Художник как начинающий интроверт, находящий обратный путь к реальности через искусство (Фрейд, 1916-17)\">Художник как начинающий интроверт, находящий обратный путь к реальности через искусство (Фрейд, 1916-17)<\/a> · <a class=\"note\" data-note=\"Регрессия на службе Я (Крис, 1952)\">Регрессия на службе Я (Крис, 1952)<\/a>", "Прегенитальные организации — оральная (каннибалическая) и садистско-анальная фазы (Фрейд, 1905, Три очерка)": "<p class=\"src\">Источник: Три очерка, Фрейд, 1905 (Очерк II, «Прегенитальные организации»)<\/p>\n\n**Тезис.** Изучение с помощью психоанализа торможений и нарушений в ходе развития позволяет распознать зачатки и предварительные ступени такой организации частичных влечений, которые тоже составляют своего рода сексуальный «режим». В норме эти фазы полового устройства проходятся гладко, выдавая себя лишь намёками, и становятся заметны грубому наблюдению только в патологических случаях.\n\n**Аргументы.** Организации половой жизни, в которых генитальные зоны ещё не заняли своей господствующей роли, назовём **прегенитальными**. Их можно выделить две, напоминающие возврат к раннеживотным состояниям. Первая прегенитальная организация — **оральная**, или, если угодно, **каннибалическая**: половая деятельность здесь ещё не отделена от приёма пищи, противоположности внутри неё ещё не дифференцированы, объект одной деятельности есть и объект другой, а сексуальная цель состоит во **включении объекта в себя** — прообразе того, что позднее сыграет столь значительную психическую роль под именем **идентификации**. Остатком этой фиктивной, навязанной нам патологией фазы организации можно считать сладострастное сосание, в котором сексуальная деятельность, уже отделившись от питающей, отказалась от чужого объекта в пользу объекта на собственном теле (сноска: об остатках этой фазы у взрослых невротиков см. работу Абрахама «Исследования о древнейшей прегенитальной ступени развития либидо»). Вторая прегенитальная фаза — **садистско-анальная** организация. Здесь уже сформирована противоположность, пронизывающая половую жизнь, но её ещё нельзя называть «мужской» и «женской» — она должна называться **активной** и **пассивной**. Активность обеспечивается влечением к овладению со стороны телесной мускулатуры; как орган с пассивной сексуальной целью выступает прежде всего эрогенная слизистая кишечника; для обоих стремлений уже есть объекты, но они не совпадают между собой. Наряду с этим другие частичные влечения действуют аутоэротически. В этой фазе, таким образом, уже доказуемы половая полярность и наличие чужого объекта; отсутствуют ещё организация под главенством размножения и его подчинение.\n\n**Вывод.** Между аутоэротической разрозненностью грудного периода и итоговым генитальным примыканием взрослой жизни лежат две промежуточные организации — оральная (влечение = включение объекта в себя = прообраз идентификации) и садистско-анальная (полярность уже есть, но как активность/пассивность, а не мужское/женское); обе не исчезают бесследно, а могут сохраняться и заявлять о себе на протяжении всей жизни.\n\n→ Амбивалентность — садистско-анальная фаза может забрать себе целую жизнь (Фрейд, 1905, Три очерка)\n→ Прегенитальные организации либидо — оральная и садистически-анальная (Фрейд, 1905, Три очерка) (краткая версия того же)\n\n→ <a class=\"note\" data-note=\"Идентификация амбивалентна с самого начала — её оральное происхождение (Фрейд, 1921, Групповая психология)\">Идентификация амбивалентна с самого начала — её оральное происхождение (Фрейд, 1921, Групповая психология)<\/a> (каннибалическая фаза 1905 г. как источник формулы)\n→ Сознание вины превращает садизм в мазохизм (Фрейд, 1919, Ребёнка бьют)\n→ Мазохизм проходит фазы либидо — от страха быть съеденным до коитуса и родов (Фрейд, 1924)", "Призраки становятся предками (Лёвальд, 1960)": "В статье «О терапевтическом действии психоанализа» Ханс Лёвальд описывает аналитика не только как экран для проекций, но и как **новый объект**: в его восприятии пациент встречает более цельный образ самого себя — тот, к которому может вырасти.\n\nОтсюда знаменитый образ. Призраки бессознательного, говорит Лёвальд, жаждут, чтобы их отпустили из призрачной жизни и упокоили как **предков**. Пока прошлое бродит без спроса и питается живой энергией переноса, оно остаётся призраком. В анализе оно становится предком: его сила не исчезает, а переходит в новую, живую интенсивность настоящего.\n\nЭто различие между повторением и историей: призрак действует, предок рассказывается.\n\nСвязано: <a class=\"note\" data-note=\"интернализация как усиление когерентности психики (Лёвальд)\">интернализация как усиление когерентности психики (Лёвальд)<\/a> · <a class=\"note\" data-note=\"Перенос — промежуточное царство между болезнью и жизнью (Фрейд, 1914)\">Перенос — промежуточное царство между болезнью и жизнью (Фрейд, 1914)<\/a>", "Происхождение отвращения — «inter urinas et faeces nascimur» (Фрейд, 1905, Дора)": "<p class=\"src\">Источник: Дора, Фрейд, 1905<\/p>\n\nОтсюда Фрейд выводит происхождение отвращения: ощущение отвращения кажется первоначально реакцией на запах (позднее и на вид) экскрементов; о экскреторных функциях могут напоминать и гениталии, в особенности мужской член, поскольку этот орган служит не только сексуальной, но и функции мочеиспускания — причём эта последняя функция известна раньше и в досексуальное время единственно известна. Так отвращение попадает в число аффективных проявлений сексуальной жизни; это «inter urinas et faeces nascimur» церковного отца, неотделимо присущее половой жизни вопреки всем идеализирующим усилиям. Фрейд особо подчёркивает, что не считает проблему решённой указанием на этот ассоциативный путь: то, что ассоциация может быть пробуждена, ещё не объясняет, что она и в самом деле пробуждается — в нормальных условиях этого не происходит; знание путей не делает излишним знание сил, которые эти пути протаптывают.\n\n→ Легенда о самоубийстве в лесу придумана отцом (Фрейд, 1905, Дора)", "Протообъект — имя для того, что есть там, где объектов нет (Балинт)": "В области созидания «объектов» нет, но субъект в ней почти всегда — или какую-то часть времени — не вполне одинок. Трудность в том, что взрослый конвенциональный язык не располагает средствами описать или хотя бы указать на это «нечто».\n\nЧтобы получить возможность о нём говорить, Балинт предлагает термин **«протообъект»**; годились бы и «объект-эмбрион», и немецкое Objekt-Anlage. Протообъекты настолько примитивны, что не могут считаться организованными или целостными; вербальные и эдиповы взаимодействия между внешними объектами и этими новыми объектами становятся возможны лишь после того, как работа созидания сообщит им какую-то структуру и целостность.\n\nБалинт замечает, что Бион, если он правильно его понял, столкнулся с той же трудностью и ответил на неё терминами α- и β-элементов и α-функции.\n\nДля темы важна сама операция: обнаружив область, где переноса нет, Балинт не оставляет её пустой, а вводит имя для того минимального «нечто», что там присутствует. Так граница отсутствия оказывается населённой.\n\n<p class=\"src\">Источник: Балиндт, базис дефект<\/p>\n\n## Связанные заметки\n\n→ <a class=\"note\" data-note=\"Нет внешнего объекта — нет переноса, и метод бессилен (Балинт)\">Нет внешнего объекта — нет переноса, и метод бессилен (Балинт)<\/a>\n→ <a class=\"note\" data-note=\"Область созидания — третий уровень психики без внешнего объекта (Балинт)\">Область созидания — третий уровень психики без внешнего объекта (Балинт)<\/a>\n→ как по биону младенец решает вопрос что происходит\n→ Связывание как эмоциональная функция, а не объект (Бион, через Чивитарезе)", "Протопамять как непереваренный элемент — Ройтман и модель контейнер-контейнируемое у Биона": "<a class=\"note\" data-note=\"Связывание-контейнирование-мышление\">Связывание-контейнирование-мышление<\/a> описывает бионовскую модель «контейнер — контейнируемое»: непереносимые эмоции (β-элементы) проецируются в грудь-контейнер, чтобы вернуться детоксицированными, переработанными в мысль (α-элементы); устойчивая патологическая проективная идентификация — когда контейнирования не случилось — лежит в основании нарушений мышления. Ройтман применяет ровно эту же логику к памяти терапевта: протопамять — это статичные, однослойные, расщеплённые впечатления, β-элементы травматического опыта, которые не были контейнированы и переработаны в момент, когда возникли, — а «сноподобная память» (Ревери как dream-like memory — проторецепторная память терапевта (Ройтман)) есть в точности α-элемент, продукт контейнирования, доступный дальнейшему переформулированию.\n\n**Совпадение по существу.** Оба текста используют одну и ту же ось «непереваренное ↔ переработанное» для описания разных материалов: в Проективная идентификация (раздел про Биона) это эмоция пациента, проецируемая в аналитика-контейнер; у Ройтмана — это собственная детская травма терапевта, которая ждёт не проекции в другого, а трансформации через самоанализ (случай деда, Клинический пример — Амос и дед терапевта, война как оборванный крик двух поколений (Ройтман)). Разница в направлении процесса (входящее контейнирование чужого опыта vs. внутренняя переработка собственного) не отменяет тождества механизма: и там, и там α-функция — это то, что превращает статичный, непредставимый элемент в подвижную мысль, открытую дальнейшей связи с другими мыслями.\n\n**Зачем это важно клинически.** Из этого совпадения следует нетривиальный вывод статьи Ройтмана: терапевт не может контейнировать β-элементы пациента, если его собственные родственные β-элементы (протопамять) не прошли ту же трансформацию. Способность быть контейнером для другого требует, чтобы аналитик прежде — или одновременно — стал контейнером для собственной недосмотренной истории.\n\n<p class=\"src\">Источник: синтез автора (не цитата ни из одного из исходных текстов)<\/p>\n**Связанные заметки:** <a class=\"note\" data-note=\"Связывание-контейнирование-мышление\">Связывание-контейнирование-мышление<\/a>, Проективная идентификация, Ревери как dream-like memory — проторецепторная память терапевта (Ройтман), Функция аналитика как контейнера", "Регрессия на службе Я (Крис, 1952)": "Эрнст Крис в «Психоаналитических исследованиях искусства» объясняет, как художнику удаётся черпать из самых ранних, «первобытных» слоёв психики и не тонуть в них. Его формула — **регрессия на службе Я**.\n\nХудожник на время ослабляет контроль Я и пускает в сознание первичный процесс — образы, сгущения, ассоциации, как во сне. Но эта регрессия **частичная, обратимая и подконтрольная**: затем вторичный процесс оформляет найденный материал, придаёт ему форму, ритм, композицию.\n\nОтличие от патологической регрессии — именно в обратимости. Творческий человек уходит вглубь и возвращается; человек, захваченный регрессией, — нет. То же различие видно между искусством и массовым экстазом.\n\nСвязано: <a class=\"note\" data-note=\"Искусство как примирение двух принципов — художник как окольный герой (Фрейд, 1911)\">Искусство как примирение двух принципов — художник как окольный герой (Фрейд, 1911)<\/a> · <a class=\"note\" data-note=\"Взаимная индукция аффекта в массе (Фрейд, 1921, Групповая психология)\">Взаимная индукция аффекта в массе (Фрейд, 1921, Групповая психология)<\/a> · <a class=\"note\" data-note=\"Писатель и фантазирование — эстетическая премия (Фрейд, 1908)\">Писатель и фантазирование — эстетическая премия (Фрейд, 1908)<\/a>", "Роль \"достаточно хорошей матери\" для формирования способности к творчеству": "Винникотт утверждает, что творчество важно для конструирования смысла жизни и развития личности. Он подчеркивает, что недостаток поддержки (\"достаточно хорошей матери\") в детстве может препятствовать развитию творческого потенциала. Аналитик должен помочь создать безопасное пространство для клиента, где можно развивать творческие способности.\n\n<p class=\"src\">Источник: Nachträglichkeit и психоаналитическая креативность<\/p>\n\n**Связанные заметки (Талеб):** сверхзаботливая мать подавляет антихрупкость ребёнка", "Связывание-контейнирование-мышление": "Проективная идентификация позволяет Биону сформулировать модель «контейнер — контейнируемое»: контейнируемое может разрывать контейнер, либо, наоборот, сдавливаться и удушаться контейнером, либо между ними происходит взаимная адаптация. Согласно этой модели, младенец проецирует часть своего психического мира — неконтролируемые эмоции (контейнируемое) — в хорошую грудь-контейнер, чтобы получить их обратно «дезинтоксицированными», в более переносимом виде. Так механизм проективной идентификации запускается оральными отношениями рта и груди.\n\nУстойчивость патологической проективной идентификации лежит в основании нарушений мышления. Непереносимость фрустраций ведёт к включению этого механизма: ответом на фрустрацию могло бы быть производство α-элементов (представление вещи-в-себе), но вместо этого производятся β-элементы, неотличимые от вещей-в-себе. При этом проективная идентификация в норме лежит в основании самой способности мыслить — она «прописывает мысль до мысли».\n\nТаким образом связывание (через проективную идентификацию), контейнирование (модель «контейнер — контейнируемое») и мышление (производство α-элементов) у Биона оказываются связаны одной линией: контейнирование эмоций — это то, через что непереваренное (β-элементы) может быть переработано в мысль.\n\n<p class=\"src\">Источник: Аппарат мышления<\/p>\n\n**Связанные заметки:** Мышление, Мысли, Аппарат мышления, Проективная идентификация, стрессоры как информация", "Символическое уравнение — символ и вещь совпадают (Сегал, 1957)": "Ханна Сегал различает две формы символа. При **символическом представлении** символ замещает объект, но не сливается с ним: между ними остаётся дистанция, и именно она позволяет думать, играть, творить. При **символическом уравнении** символ переживается как сам объект.\n\nЕё знаменитый пример — пациент-шизофреник, который перестал играть на скрипке: играть на ней публично для него значило мастурбировать на людях. Скрипка не изображала, а **была** тем, что символизировала.\n\nСпособность к подлинному символу, по Сегал, рождается в депрессивной позиции: нужно признать, что объект отделён и может быть утрачен, — и тогда символ становится способом сохранить его в отсутствие. Где этого не случилось, остаётся конкретность: принять в себя значит съесть, быть принятым — значит быть съеденным.\n\nСвязано: <a class=\"note\" data-note=\"Символическое уравнивание\">Символическое уравнивание<\/a> · <a class=\"note\" data-note=\"Первичная и вторичная символизация\">Первичная и вторичная символизация<\/a> · <a class=\"note\" data-note=\"Частичный и целый объект — путь к депрессивной позиции (Кляйн)\">Частичный и целый объект — путь к депрессивной позиции (Кляйн)<\/a>", "Символическое уравнивание": "Руссийон, 2011: \nУ Руссийона нет термина «символическое уравнение», но он описывает тот же феномен. Речь идёт о случаях, когда **репрезентация не отделяется от восприятия или галлюцинации** и удерживает **присутствие объекта**, а не его отсутствие. В такой ситуации не возникает дистанции, необходимой для символизации, и вместо символической трансформации появляются **эквиваленты** — телесные, аффективные или процессуальные формы, свидетельствующие о неинтегрированности первичной психической материи.\n\n→ Символизация при психотических состояниях — тот же провал символизации, доведённый до предела (галлюцинация, бред)", "Скука аналитика как главная опасность переноса-слияния и близнецового (Кохут)": "Проблемы аналитика при переносе-слиянии и близнецовом переносе (переносе по типу второго «я») совершенно иные, чем при зеркальном. Самые распространённые опасности здесь — **скука, отсутствие эмоциональной вовлечённости в отношения с пациентом и недостаточная концентрация внимания.**\n\nКохут перечисляет и вторичные реакции, в которые это выливается: открытое проявление недовольства, увещевания, постоянное стремление интерпретировать сопротивления и прочие формы рационализируемого отыгрывания напряжения и нетерпимости.\n\nПрактический вывод для темы: скука аналитика — не пустая клетка в протоколе, а показание прибора. Она указывает на определённый тип переноса, а не на его отсутствие.\n\n<p class=\"src\">Источник: Кохут, Анализ самости (1971)<\/p>\n\n## Связанные заметки\n\n→ <a class=\"note\" data-note=\"Отсутствие объектного катексиса — почему внимание не удерживается (Кохут)\">Отсутствие объектного катексиса — почему внимание не удерживается (Кохут)<\/a>\n→ Зеркальный перенос удерживает внимание, слияние — нет (Кохут)\n→ Защитная скука отличается от настоящей (Кохут)\n→ <a class=\"note\" data-note=\"Когда кажется, что переноса в работе нет — карта темы\">Когда кажется, что переноса в работе нет — карта темы<\/a>", "Слабое место сублимации — доступна немногим и не даёт полной защиты от страдания (Фрейд, 1930)": "<p class=\"src\">Источник: Недовольство культурой, Фрейд, 1930<\/p>\n\n## Тезис\n\nЕщё один способ защиты от страдания — использование смещений либидо, на которые способен наш психический аппарат, придающий ему такую гибкость: цель здесь в том, чтобы перенаправить инстинктивные цели туда, где их не сможет фрустрировать внешний мир. В этом помогает **сублимация влечений** — успех наибольший, когда человек умеет в достаточной мере повысить свою способность получать удовольствие от умственной и интеллектуальной работы (радость художника в творчестве, воплощении своих фантазий, или учёного — в решении задач и открытии истин).\n\n## Слабость метода\n\nСлабое место этого метода, однако, в том, что он не общедоступен: он доступен лишь немногим, предполагает особые дарования и склонности, не столь часто встречающиеся в достаточной степени. И даже этим немногим он не обеспечивает полной защиты от страдания — не даёт неуязвимой брони против стрел судьбы и, как правило, оказывается бессилен, когда источником страдания становится собственное тело человека.\n\n## Ещё один вариант — иллюзии фантазии\n\nЕщё дальше в том же направлении (независимость от внешнего мира через обращение внутрь) идёт следующий метод — удовлетворение через иллюзии, признаваемые таковыми, но не позволяющие несовпадению с реальностью помешать доставляемому ими наслаждению; во главе этих фантазийных удовольствий стоит наслаждение произведениями искусства — но и оно действует лишь как лёгкий наркотик, дающий временное убежище, но не позволяющий забыть подлинное горе.\n\n## Значение\n\nОграничение, характерное для позднего, менее оптимистичного Фрейда: даже самый «благородный» из доступных путей к счастью — творческий и интеллектуальный труд — остаётся элитарным и частичным решением, что подготавливает более пессимистичный общий тон всей книги.\n\n→ Каталог техник поиска счастья (Фрейд, 1930)", "Смешение с объектом как самая примитивная форма объектного отношения (Розенфельд, 1952)": "Все исследованные Розенфельдом шизофреники обнаруживали одну форму объектного отношения особенно ясно: **как только шизофреник приближается к объекту в любви или в ненависти, он словно смешивается с этим объектом.**\n\nЭто не только идентификация через интроекцию, но импульсы и фантазии войти внутрь объекта целиком или частями, чтобы им управлять, — то, что Кляйн назвала проективной идентификацией. Такие импульсы можно считать самым примитивным типом объектного отношения, действующим с рождения; они окрашивают оральные, анальные, уретральные и генитальные побуждения.\n\nПациент описал это сам. Своё вхождение в объект он называл «идти до конца» и сформулировал последствие: «если идёшь до конца, обратно всё не заберёшь». Смятение, о котором он говорил, — не пустота, а осознание, что ты смешан с кем-то другим.\n\nРозенфельд возражает Нунбергу (1920), объяснявшему такие состояния нарциссической идентификацией: сама по себе интроекция внешнего объекта к смешению с ним не ведёт — во всех наблюдавшихся им случаях присутствовала ещё и проективная идентификация. Желание войти в объект определяется не только всемогущим стремлением уничтожить дистанцию, но и стремлением избавиться от времени: дистанция от объекта неразрывно связана с осознанием течения времени, ведь стоит объекта захотеть, как удовлетворения требуют немедленно.\n\n<p class=\"src\">Источник: Розенфельд, Психотические состояния (1965)<\/p>\n\n## Связанные заметки\n\n→ Отстранённость второй сессии оказалась проективной идентификацией (Розенфельд, 1952)\n→ психотический перенос как частный случай проективной идентификации\n→ Проективная идентификация\n→ Защита от осознания отдельности делает нарциссический перенос невидимым (Розенфельд, 1964)", "Страх падения и страх растворения — различие по Тастин": "Тастин (1986) проводит принципиальное различие между двумя примитивными тревогами:\n\n## Страх падения\n- Предполагает, что **селф достаточно кристаллизовано** и продолжает существовать во время падения и после него\n- Это страх **выпасть из рук поддерживающего другого**\n- Селф остаётся целым, объект воспринимается как отвергающий/бросающий\n- Возможен только когда **интернализована некоторая способность к контейнированию**\n\n## Страх растворения\n- Селф и объект **не дифференцированы** — слиты\n- Исчезновение объекта = уничтожение селф\n- Отделение от объекта воспринимается как **психическая смерть**\n- Нет внутреннего психического позвоночника, который удерживает\n\n## Ключевое различие\n> Страх падения предполагает наличие **психического позвоночника** (Анзье, 1989), который удерживает и определяет существование селф, предотвращая полное падение, ведущее к уничтожению. Страх растворения возникает там, где этого позвоночника нет.\n\n→ Психический позвоночник — Анзье\n→ <a class=\"note\" data-note=\"Черная дыра — Тастин\">Черная дыра — Тастин<\/a>\n→ Адгезивная идентификация как защита от страха падения\n→ Тревога-потери-селф по Гаддини\n\n## Источник\n→ Шеллекес, Ужас падения и растворения\nTustin, F. (1986). Autistic Barriers in Neurotic Patients. London: Karnac Books.", "Страх распада — катастрофа, которая уже случилась (Винникотт, 1974)": "В поздней работе, опубликованной посмертно в 1974 году, Винникотт предлагает парадоксальную мысль: пациент, который боится сойти с ума, развалиться, исчезнуть, боится того, что **уже произошло** — в самом раннем детстве.\n\nТогда это случилось, но не было **пережито**: не было ещё Я, способного вместить опыт, и не было среды, которая помогла бы его выдержать. Винникотт называет такие состояния «немыслимыми тревогами»: распадение на части, бесконечное падение, утрата связи с телом, утрата ориентации. Не пережитое не может стать прошлым — поэтому оно ждёт впереди, как будущая катастрофа.\n\nЗадача анализа — позволить пациенту впервые пережить это в настоящем, в переносе, рядом с кем-то, кто выдерживает.\n\nСвязано: <a class=\"note\" data-note=\"Холдинг и страх падения — Винникотт\">Холдинг и страх падения — Винникотт<\/a> · <a class=\"note\" data-note=\"Страх падения и страх растворения — различие по Тастин\">Страх падения и страх растворения — различие по Тастин<\/a> · <a class=\"note\" data-note=\"Черная дыра — Тастин\">Черная дыра — Тастин<\/a>", "Сублимация — карта области (Фрейд)": "**Идея.** Сублимация — самая оптимистичная из судеб влечения: сексуальная энергия меняет цель на несексуальную и питает работу, искусство, познание, дружбу. У Фрейда она проходит три ступени осмысления: третий исход конституции наряду с перверсией и неврозом (1905), одна из четырёх судеб влечения (1915) и, наконец, механизм с внутренней ценой (1923): чтобы сублимировать, Я должно сперва забрать либидо себе, десексуализировать его — а значит, всякая сублимация втайне сродни утрате объекта. При этом Фрейд честен в двух признаниях: механизм до конца не объяснён, а сам путь «доступен немногим».\n\n**Станции линии:**\n\n- **Третий исход (1905)** → Сублимация как третий исход — характер строится из подавленных перверсных влечений (Фрейд, 1905, Три очерка), Реактивные образования и сублимация строят латентный период (Фрейд, 1905, Три очерка), Сексуальность и телесные функции сообщаются в обе стороны (Фрейд, 1905, Три очерка)\n- **Образцовый случай: Леонардо (1910)** → Реконструкция развития Леонардо — сублимация либидо в жажду знания и регрессии (Фрейд, 1910), Три судьбы влечения к исследованию — торможение, навязчивое умствование, сублимация (Фрейд, 1910), Улыбка Моны Лизы и две матери в святой Анне (Фрейд, 1910), Границы психоанализа в биографии — доля свободы и органическая основа вытеснения и сублимации (Фрейд, 1910), Сексуализация мышления через влечение к знанию — раздумье как навязчивый симптом (Фрейд, 1909, Человек-Крыса) (контрпример: неудача сублимации исследования)\n- **Место в метапсихологии (1914–1915)** → Четыре судьбы влечения — обращение в противоположность, поворот на себя, вытеснение, сублимация (Фрейд, 1915), Сублимация и идеализация — различение по объекту приложения (Фрейд, 1914), Сублимация и пластичность либидо как защита от патогенного действия отказа (Фрейд, 1916-17)\n- **Сублимированная гомосексуальность и социальное чувство** → Сублимированная гомосексуальность как эротический вклад в дружбу и общественное чувство (Фрейд, 1911, Шребер), Функциональное преимущество заторможенных влечений и их обратимость (Фрейд, 1921, Групповая психология), Любовь как культурный фактор — поворот от эгоизма к альтруизму (Фрейд, 1921, Групповая психология)\n- **Механизм и его цена (1923)** → Сублимация как десексуализация через навязывание Я себя Оно в качестве объекта любви (Фрейд, 1923), Смещаемая индифферентная энергия — десексуализированный Эрос как источник сублимации (Фрейд, 1923)\n- **Сублимация в клинике** → Сублимация садизма под влиянием немецкого учителя (Фрейд, 1918, Человек-Волк), Сублимация мазохизма через отождествление с Христом (Фрейд, 1918, Человек-Волк), Работа религии — сублимация и отождествление с Христом (Фрейд, 1918, Человек-Волк), Влияние зависти к пенису на характер и её сублимация (Фрейд, 1933)\n- **Опора культуры — и путь для немногих (1930)** → Сублимация и отказ от влечений — два механизма культуры (Фрейд, 1930), Каталог техник поиска счастья (Фрейд, 1930), <a class=\"note\" data-note=\"Слабое место сублимации — доступна немногим и не даёт полной защиты от страдания (Фрейд, 1930)\">Слабое место сублимации — доступна немногим и не даёт полной защиты от страдания (Фрейд, 1930)<\/a>, Наслаждение красотой — чувство с заторможенной целью (Фрейд, 1930), Любовь как центр жизни — уязвимейший путь к счастью (Фрейд, 1930), Искусство как заместительное удовлетворение древнейших культурных отказов (Фрейд, 1927), Спекулятивный миф об укрощении огня через отказ от мочеиспускания на пламя (Фрейд, 1930)\n\n**Почему это узел.** Сублимация — мост между самой интимной клиникой (судьба одного влечения) и самой широкой теорией культуры: одна и та же операция объясняет характер, дружбу, искусство и науку. При этом она осталась у Фрейда наименее разработанным из механизмов — он сам называл вопрос открытым, и именно отсюда выросли позднейшие споры (у нас в базе — через групповой трек и Винникотта). Родственные узлы: Стадии либидо — карта области (Фрейд), Культура и религия — карта области (Фрейд), Фантазия — карта области (Фрейд) (искусство как обратный путь из фантазии), Нарциссизм — карта области (Фрейд).", "Таласса — тяга вернуться в материнское лоно (Ференци, 1924)": "В «Талассе» Шандор Ференци строит смелую биоаналитическую гипотезу: в основе сексуальности лежит стремление **вернуться в материнское лоно** — в состояние, где нет отдельности, нужды и границ.\n\nГенитальное соединение он понимает как символическое и частичное возвращение туда, а сон — как ежевечерний уход в подобие внутриутробного покоя. Ференци идёт дальше: за тягой к лону стоит филогенетическая «память о море», из которого жизнь когда-то вышла на сушу, — отсюда название книги (thalassa — море по-гречески).\n\nНезависимо от того, насколько принимать её биологию, «Таласса» дала психоанализу образ **регрессии как возвращения** — желания отменить отдельность и вернуться туда, где тебя ещё не отделили от мира.\n\nСвязано: <a class=\"note\" data-note=\"Область созидания — третий уровень психики без внешнего объекта (Балинт)\">Область созидания — третий уровень психики без внешнего объекта (Балинт)<\/a> · <a class=\"note\" data-note=\"Нет внешнего объекта — нет переноса, и метод бессилен (Балинт)\">Нет внешнего объекта — нет переноса, и метод бессилен (Балинт)<\/a> · <a class=\"note\" data-note=\"Протообъект — имя для того, что есть там, где объектов нет (Балинт)\">Протообъект — имя для того, что есть там, где объектов нет (Балинт)<\/a>", "Фетишизм — условие пола, детская фиксация и символическая связь (Фрейд, 1905, Три очерка)": "<p class=\"src\">Источник: Три очерка, Фрейд, 1905 (Очерк I, раздел «Анатомические превышения»)<\/p>\n\n**Тезис.** Патологический случай фетишизма наступает лишь тогда, когда стремление к фетишу закрепляется сверх обычного условия и занимает место нормальной цели, а фетиш отделяется от конкретного лица и становится единственным сексуальным объектом; в противном случае некоторая доля фетишизма — обычная черта нормальной влюблённости.\n\n**Аргументы.** Некоторая степень такого фетишизма регулярно свойственна нормальной любви, особенно на тех стадиях влюблённости, когда нормальная сексуальная цель недостижима или её осуществление отложено (цитата из «Фауста»: «Дай мне платок с её груди, подвязку моей любовной страсти!»). Определённое ослабление стремления к нормальной сексуальной цели («исполнительская слабость полового аппарата») выступает предпосылкой для всех случаев фетишизма — это конституциональное условие; психоанализ же указала на добавочное, случайное условие — раннее сексуальное запугивание, отталкивающее от нормальной цели и побуждающее искать ей замену. Связь с нормой обеспечивается психологически неизбежной сексуальной переоценкой объекта, неминуемо распространяющейся на всё, что с ним ассоциативно связано. В выборе фетиша, как первым утверждал Бине и затем подтвердили многочисленные наблюдения, сказывается длящееся влияние сексуального впечатления, полученного обычно в раннем детстве, — сопоставимое с пословичной прочностью первой любви у нормальных людей («On revient toujours à ses premiers amours»). Более глубокое психоаналитическое исследование скорректировало утверждение Бине: за первым воспоминанием о появлении фетиша скрывается уже угасшая и забытая фаза сексуального развития, представленная фетишем как «покрывающим воспоминанием», — обращение этой ранней фазы к фетишизму и выбор самого фетиша конституционально предопределены. В иных случаях к замене объекта фетишем ведёт обычно неосознаваемая самим человеком символическая связь мыслей (нога — древний сексуальный символ уже в мифах; башмачок или туфля соответственно — символ женских гениталий; «мех» обязан своей ролью фетиша, вероятно, ассоциации с волосами на лобке) — и такая символика тоже, по-видимому, не всегда независима от сексуальных переживаний детства. Психоанализ восполнила один из пробелов в понимании фетишизма, указав на значение утраченного через вытеснение копрофильного обонятельного наслаждения при выборе фетиша: нога и волосы — сильно пахнущие объекты, возводимые в фетиш именно после отказа от ставшего неприятным обонятельного ощущения (соответствующая перверсия — фетишизм ноги — избирает сексуальным объектом именно грязную, дурно пахнущую ногу); дополнительное объяснение даёт детская сексуальная теория — нога замещает тяжело переживаемое отсутствие пениса у женщины. В части случаев фетишизма ноги показано, что изначально направленное на гениталии влечение к разглядыванию, желавшее приблизиться к объекту снизу, было остановлено на этом пути запретом и вытеснением — отчего и закрепилось на ноге или башмаке как фетише, а женские гениталии при этом, соответственно детскому ожиданию, представлялись как мужские.\n\n**Вывод.** Фетишизм демонстрирует общий закон, применимый далеко за пределами самого фетишизма: сексуальный интерес легко и незаметно смещается с генитальной цели на ассоциативно связанные с объектом детали — и именно раннее детское впечатление, часто забытое, определяет, куда именно.\n\n→ Прикосновение и разглядывание — путь к вуайеризму и эксгибиционизму (Фрейд, 1905, Три очерка)\n→ Первое объяснение — перверсия как преждевременно обособившаяся компонента (Фрейд, 1919, Ребёнка бьют)\n→ Фетиш как побочная находка — довольные приверженцы и блеск на носу (Фрейд, 1927, Фетишизм)\n→ Покровные воспоминания — незначительные детские сцены как заместители вытесненного (Фрейд, 1901)", "Холдинг и страх падения — Винникотт": "## Холдинг и моторное развитие\n\nРазвитие селф тесно связано с чувством контроля и развитием моторных навыков. Концепция **холдинга** Винникотта в своём конкретном аспекте описывает физическое удержание ребёнка, который ещё не может держаться прямо самостоятельно.\n\nРазвивающаяся двигательная независимость позволяет:\n- дистанцироваться от объекта\n- физическое расстояние → психическая жизнь в отсутствие физического присутствия объекта\n\n## Падение с кушетки\n\nВинникотт (1949) рассматривает падение с кушетки как аналог опыта падения с колен аналитика — повторное переживание травмы рождения и разлуки. Сопровождается желанием быть подхваченным аналитиком из глубин падения.\n\n## Головокружение в конце сессии (Ференци, 1914)\n\nФеренци описывает головокружение при вставании с кушетки как:\n- переход между принципом удовольствия и принципом реальности (Фрейд)\n- чувство отрыва от аналитической поддержки (объектные отношения)\n\nГоловокружение в конце сессии = **сигнал тела** о том, что аналитическое контейнирование претерпело неудачу.\n\n→ Психический позвоночник — Анзье\n→ <a class=\"note\" data-note=\"Страх падения и страх растворения — различие по Тастин\">Страх падения и страх растворения — различие по Тастин<\/a>\n\n## Связанные заметки из базы\n\nДругая грань холдинга у Винникотта — не про страх падения, а про создание пространства для игры и творчества:\n→ Концепция промежуточной зоны по Винникотту\n→ Переходный объект и промежуточная зона\n→ Творчество в аналитической технике\n\n## Источник\n→ Шеллекес, Ужас падения и растворения\nWinnicott, D.W. (1949). Mind and Its Relation to Psyche-Soma.\nWinnicott, D.W. (1954). Metapsychological and Clinical Aspects of Regression.\nFerenczi, S. (1914). Sensations of giddiness at the end of the psycho-analytic session.\n**Связанные заметки (Талеб):** сверхзаботливая мать подавляет антихрупкость ребёнка", "Художник как начинающий интроверт, находящий обратный путь к реальности через искусство (Фрейд, 1916-17)": "<p class=\"src\">Источник: Вводные лекции, Фрейд, 1916-17 (лекция 23)<\/p>\n\n## Тезис\n\nИз фантазии существует путь обратно к реальности — и это путь **искусства**. Художник — «начинающий интроверт», недалёкий от невротика: он движим слишком мощными инстинктивными нуждами, желает почестей, власти, богатства, славы и любви женщин, но лишён средств добиться этих удовлетворений в реальности. Как и всякий неудовлетворённый человек, он отворачивается от реальности, перенося весь интерес и всё своё либидо на разработку воображаемых желаний — путь, который легко мог бы привести к неврозу; неспроста художники так часто страдают от частичного торможения своих способностей неврозом.\n\n## Возврат к реальности\n\nНо конституция художника, судя по всему, наделена сильной способностью к **сублимации** и к смещению вытеснений, определяющих его конфликты, — именно этим путём художник и находит дорогу обратно к реальности. Не он один живёт жизнью воображения — сумеречное царство фантазии санкционировано всем человечеством, и всякая голодная душа ищет там помощи и сочувствия; но для не-художника способность извлекать удовлетворение из воображаемых источников крайне ограничена — неумолимое вытеснение вынуждает довольствоваться скудными сознательными дневными грёзами. У настоящего художника средств больше: прежде всего он умеет так разработать свои дневные грёзы, что они теряют свой сугубо личный характер (эта часть аргумента развёрнута далее в тексте лекции, обрывающемся здесь на середине фразы).\n\n## Значение\n\nКомпактный набросок теории искусства и художника как «удачливого интроверта», к которой Фрейд неоднократно возвращается в других работах (Леонардо, «Художник и фантазирование»); связывает всю теорию симптомообразования (интроверсия → конфликт → симптом) с позитивным, не патологическим выходом из того же тупика — сублимацией через творчество.\n\n→ Интроверсия — отход либидо к фантазии как промежуточный шаг к симптому (Фрейд, 1916-17)\n→ Три судьбы влечения к исследованию — торможение, навязчивое умствование, сублимация (Фрейд, 1910)\n→ Реконструкция развития Леонардо — сублимация либидо в жажду знания и регрессии (Фрейд, 1910)\n→ Наука как отречение от принципа удовольствия (Фрейд, 1910, Выбор объекта)", "Частичный и целый объект — путь к депрессивной позиции (Кляйн)": "В самом начале жизни, по Кляйн, младенец имеет дело не с матерью как человеком, а с **частичными объектами** — прежде всего с грудью. Грудь расщеплена на хорошую, которая кормит, и плохую, которая исчезает и мучает. Это параноидно-шизоидная позиция: мир разделён на идеальное и преследующее.\n\nС **депрессивной позицией** (Кляйн описала её в 1935 году) младенец постепенно открывает, что хорошая и плохая грудь принадлежат одной матери — целому человеку, отдельному от него, которого он и любит, и ненавидит. Вместе с целым объектом приходят вина за собственную агрессию, страх его потерять и желание восстановить повреждённое.\n\nЦелый объект — это человек со своей жизнью, которого можно любить и можно потерять. Частичный — функция, которую можно взять и выбросить.\n\nСвязано: <a class=\"note\" data-note=\"частичные объекты\">частичные объекты<\/a> · <a class=\"note\" data-note=\"Обретение объекта как повторное обретение — грудь матери как прототип всякой любви (Фрейд, 1905, Три очерка)\">Обретение объекта как повторное обретение — грудь матери как прототип всякой любви (Фрейд, 1905, Три очерка)<\/a> · <a class=\"note\" data-note=\"Жадность, зависть и благодарность (Кляйн, 1957)\">Жадность, зависть и благодарность (Кляйн, 1957)<\/a>", "Черная дыра — Тастин": "Концепт «черной дыры» описывает переживание **полного отсутствия удерживающей структуры**, при котором психика чувствует себя засасываемой в небытие.\n\n## Суть концепта\n\nВ отсутствие прочного контакта с объектом способность личности к психическому выживанию обрушивается. Возникает ощущение **падения в бездну**, всасывания в пустоту.\n\nЭто состояние характеризуется:\n- отсутствием трёхмерности и внутреннего психического пространства\n- доминированием **растворения**, а не расщепления или диссоциации\n- отсутствием тревоги в классическом смысле — вместо неё **пустота**\n\n> «Подобные дыры не имеют психической репрезентации, но распространяют сущность своего присутствия как дыры, словно частицы пыли, которые распространяются на все уровни психического опыта» (Шеллекес, по Тастин)\n\n## Важное уточнение\nМы говорим не о тревоге, которую активирует влечение к смерти (Кляйн), а о **первичном состоянии дефицита** — отсутствии поддерживающей структуры. Тревога здесь вторична и проистекает из чувства пустоты.\n\n→ <a class=\"note\" data-note=\"Страх падения и страх растворения — различие по Тастин\">Страх падения и страх растворения — различие по Тастин<\/a>\n→ Адгезивная идентификация как защита от страха падения\n→ Психический позвоночник — Анзье\n→ Клинический случай Ноа — слияние с объектом и страх растворения\n\n## Источники\n→ Шеллекес, Ужас падения и растворения\nTustin, F. (1981). Autistic States in Children. London: Routledge.\nTustin, F. (1986). Autistic Barriers in Neurotic Patients. London: Karnac Books.\nGrotstein, J.S. (1990). Nothingness, meaninglessness, chaos and the \"black hole\". Contemp. Psychoanal., 26: 257-290.\n\n→ идентификация — от Фрейда до групповой организации психосексуального развития", "Шкала переноса «Меркалли» — нулевой уровень не есть отсутствие (Ферро)": "По образцу шкалы Меркалли, измеряющей силу землетрясения, Ферро строит шкалу интенсивности переноса — симметричную его же шкале контрпереноса.\n\n**Нулевой уровень переноса: «Это не отсутствие переноса, что, как мне кажется, в анализе является невозможным».** Это положение на прочном основании, где перенос происходит довольно естественно и сопровождается самое большее некоторым брожением, но никак не подземными толчками. Над переносом здесь работает поле; сам перенос активирует силовые линии и движения в поле — подобно тому, как водяные потоки или ветер приводят в движение мельницы.\n\nТезис сильный и стоит отдельно от прочих в теме: у Розенфельда и Кохута перенос при кажущемся отсутствии всё-таки прячется и его надо распознать, а у Ферро прятаться нечему — при нулевом уровне перенос делает свою работу открыто, просто не в форме высказываний об аналитике. Искать его в жалобах и обращениях к аналитику значит искать не там, где он есть.\n\n<p class=\"src\">Источник: Ферро, Избегание эмоций, проживание эмоций (2023)<\/p>\n\n## Связанные заметки\n\n→ Оазис Валентины — как выглядит нулевой уровень (Ферро)\n→ Уровни контрпереноса — от поля-рассказчика до разрыва сеттинга (Ферро)\n→ Периоды, когда «ничего не происходит» — работа нарциссического переноса (Ромашкевич о Кохуте)\n→ Аналитическое поле", "Экстремальные переносы — бета-экраны для активации нерецептивного аналитика (Ферро)": "На противоположном от нулевого уровня конце шкалы Ферро помещает сильный негативный и эротический перенос. В обоих он видит одно и то же: **отчаянную потребность что-то сообщить, встретившуюся с неготовностью аналитика стать проницаемым.** Вследствие этого экстремальные переносы являются по сути бета-экранами, которые служат для активации нерецептивного аналитика.\n\nФерро оговаривается, что персонифицирует силы, совместно присутствующие в поле, самовольным образом, — то есть речь не о намерении пациента, а о движении поля.\n\nОба края шкалы, таким образом, говорят об аналитике не меньше, чем о пациенте: на нулевом уровне перенос не виден, потому что поле справляется само; на четвёртом он оглушителен, потому что не справляется никто. Кохут описывает ту же ситуацию с другой стороны — как незаметное препятствование аналитика установлению зеркального переноса.\n\n<p class=\"src\">Источник: Ферро, Избегание эмоций, проживание эмоций (2023)<\/p>\n\n## Связанные заметки\n\n→ Аналитик может незаметно мешать установлению зеркального переноса (Кохут)\n→ Уровни контрпереноса — от поля-рассказчика до разрыва сеттинга (Ферро)\n→ <a class=\"note\" data-note=\"Шкала переноса «Меркалли» — нулевой уровень не есть отсутствие (Ферро)\">Шкала переноса «Меркалли» — нулевой уровень не есть отсутствие (Ферро)<\/a>\n→ Травма как переполнение β-элементами", "интернализация как усиление когерентности психики (Лёвальд)": "Пайнс разбирает, как Ханс Лёвальд использует принцип когерентности, введённый Фрейдом (различение когерентного Эго и вытесненного), чтобы выстроить теорию интернализации. У Лёвальда три тезиса: то, что интернализуется, становится неотъемлемой частью когерентного Эго; то, что вытесняется, отщепляется от когерентного Эго; Супер-Эго — это дальнейшая дифференциация того же когерентного Эго. Отсюда важное методологическое требование Лёвальда: нужно чётче, чем это делал сам Фрейд, различать процессы вытеснения и процессы интернализации — последние создают и наращивают когерентную интеграцию психики как целого, тогда как вытеснение, напротив, работает против такой организации, удерживая часть психических процессов в менее упорядоченном, более примитивном состоянии.\n\nПсихическое развитие, по Лёвальду, происходит в силовом поле взаимодействия — полярности, где мать представляет более организованный полюс, а ребёнок — менее организованный. В ходе развития ребёнок постепенно перенимает и усваивает черты более организованного полюса — матери; там, где было «другое», встаёт «self», или Эго. Механизм этого процесса — интернализация: мать организует относительно нескоординированные побуждения младенца, и через их взаимную отзывчивость ребёнок интроецирует не просто объект, а сам паттерн отклика заботящегося человека — то есть интернализируется сам процесс взаимодействия, а не отдельный объект.\n\nЛёвальд не постулирует изначально существующий отдельный психический аппарат — вместо этого он говорит об исходном психическом поле или матрице, внутри которой начинаются процессы индивидуации (в этом его отличие от поздней модели Кохута, предполагающей целостность психики с самого начала). Влечения при этом понимаются не как однонаправленные импульсы, исходящие от младенца, а как дифференцирующие и интегрирующие процессы внутри самой психической матрицы мать—дитя — то есть влечения никогда не теряют характер отношенческого феномена. Родитель вносит смысл и когерентность более высокого уровня организации в менее организованную психику младенца через процессы и паттерны взаимодействия — этот же принцип Лёвальд распространяет на аналитическую ситуацию: то, что внешняя реальность (в том числе аналитик) предлагает индивиду, — это именно движение к более высокой организации и смыслу.\n\n<p class=\"src\">Источник: Pines, Circular Reflections<\/p>\n\n**Связанные заметки:** Пайнс — когерентное бессознательное у Фрейда как модель терапевтического изменения, исцеление и излечение, когерентность и связность", "лицо матери как зеркало у Винникотта": "Центральная опора концепции зеркала у Пайнса — короткая, но программная работа Винникотта «Зеркальная роль матери и семьи в развитии ребёнка» (1971). Пайнс встраивает её в общую логику Винникотта о холдинге, обращении с ребёнком (handling) и предъявлении объекта: если младенец достаточно хорошо удержан и обихожен, в какой-то момент он начинает смотреть не столько на грудь, сколько на лицо матери.\n\nКлючевой вопрос Винникотта: что видит младенец, когда смотрит на лицо матери? Ответ: обычно — самого себя. Мать смотрит на ребёнка, и то, как выглядит её лицо, связано с тем, что она в нём видит. Если она смотрит с любовью и нежностью, ребёнок переживает себя живым и радостным. Если же мать в депрессии, не улыбается и, тем более, не может поддерживать ответный взгляд — ребёнок переживает себя безрадостным, неживым, как бы отсутствующим. В этом случае лицо матери перестаёт быть зеркалом: восприятие подменяет собой апперцепцию, обмен смыслом с миром не складывается. Такой ребёнок, повзрослев, будет озадачен обычными зеркалами — предметом, на который смотрят, но в который не всматриваются.\n\nПайнс приводит вслед за Дэвидом Шарффом идею о том, что из этого взаимного обмена взглядами в младенчестве выстраивается целая линия развития — вплоть до взрослой сексуальной и эмоциональной жизни: поцелуй, улыбка, физическая забота и близость в паре взрослых уходят корнями в разделённый взгляд, прикосновение и «разговоры» младенца с матерью. Сбои зеркалирования в младенчестве, ведущие к проблемам ложного self, затрудняют затем воссоздание зеркального опыта во взрослой сексуальной жизни.\n\nОтдельно Пайнс выделяет формулу Винникотта о психотерапии, которую считает подтверждённой собственным клиническим опытом работы с нарциссически повреждёнными пациентами: терапия — это по большей части не умные и меткие интерпретации, а долгий процесс возвращения пациенту того, что пациент сам приносит. Это прямо перекликается с идеей Кохута о зеркальном селфобъекте и с групповым феноменом зеркала: и терапевт, и группа выполняют функцию «лица», в котором участник впервые ясно видит себя.\n\n<p class=\"src\">Источник: Pines, Circular Reflections<\/p>\n**Связанные заметки:** Концепция промежуточной зоны по Винникотту, Клинический пример — феномен зеркала группы, биологическое зеркалирование в раннем взаимодействии мать-младенец", "миф о Нарциссе и Эхо как модель незеркалящихся отношений": "Пайнс подробно реконструирует миф о Нарциссе, показывая, что тема отражения в нём звучит дважды: в звуке (Эхо) и в зрении (отражённый образ в воде). Нарцисс отвергает всех, кто его любит, и в наказание сам влюбляется в отражение, не узнавая себя в нём, — он умоляет о любви существо, которое отзывается на каждое его движение, но не может к нему приблизиться. Лишь позже он понимает, что это отражение — он сам, и умирает от голода и жажды. Нимфа Эхо, отвергнутая Нарциссом, тоже не может освободиться от паралича собственного желания и умирает, превращаясь в скалы, продолжающие вторить его предсмертным стенаниям.\n\nПайнс подчёркивает: и Нарцисс, и Эхо — фигуры, у которых нет партнёра для отклика, для диалога, для взаимного питания привязанностью и любовью. Это модель безысходного диадического (двухместного) отношения без выхода, без третьего элемента, способного его опосредовать. В противоположность этому групп-аналитическая ситуация по природе своей многоперсональна и триадна (включает минимум трёх участников), поэтому вся группа целиком крайне редко оказывается захвачена подобными формами проекции: диадическая проекция получает триадную форму отзеркаливания — форму более высокого уровня развития, — и запускается благотворный цикл проекции и интроекции, способный высвобождать замкнутую психическую систему для нового психического роста.\n\nКонтраст с мифом о Персее и Медузе Горгоне важен: Персей побеждает Медузу (чей прямой взгляд обращает в камень), пользуясь начищенным до блеска щитом Афины как зеркалом — то есть смотрит не прямо, а через опосредующее отражение, «зеркало истины». Так зеркало здесь — не ловушка самолюбования (как у Нарцисса), а инструмент, позволяющий увидеть искажённый, пугающий образ себя и не быть им парализованным. Из крови обезглавленной Медузы рождается Пегас — символ творческого воображения, освобождённого после того, как пугающий образ был встречен и преодолён, а не избегнут.\n\n<p class=\"src\">Источник: Pines, Circular Reflections<\/p>\n**Связанные заметки:** зеркальные реакции Фоулкса как отправная точка, два вида зеркальных феноменов в группе", "селфобъект и зеркальный перенос у Кохута": "Разбирая источники понятия зеркала, Пайнс подробно останавливается на Кохуте. Из клинической работы с пациентами с нарциссическими расстройствами личности Кохут выводит идею о нормальной фазе развития «грандиозного self»: блеск в глазах матери, отражающий эксгибиционистскую демонстрацию ребёнка, подтверждает его самоуважение и постепенно, по мере всё большей избирательности этих откликов, направляет грандиозность в более реалистичное русло.\n\nВ модели объектных отношений Кохута есть своя линия развития: прежде чем стать отдельным объектом, другой человек долго переживается как часть самого себя. Значимый другой, инвестированный нарциссическим либидо, переживается нарциссически — как «селфобъект»: контроль над ним похож на контроль, который взрослый ожидает иметь над собственным телом и психикой. До достижения психологической отдельности младенец переживает удовольствие матери от его тела как часть собственного психического оснащения; после отделения ребёнку по-прежнему нужен «блеск в глазах матери», чтобы поддерживать нарциссическое напряжение, теперь уже применительно к очередным задачам созревания.\n\nЗеркалирование в этой схеме — один из двух полюсов кохутианского «биполярного self», второй полюс — идеализированный образ родителя. Пайнс отмечает парадокс: несмотря на огромную популярность терминов «зеркалирование» и «зеркальный перенос», введённых Кохутом, между клиническими и экспериментальными наблюдениями за реальными детьми и теоретическим корпусом селф-психологии до сих пор нет систематической связи — вклад Кохута в этой части остаётся скорее клинически убедительным, чем эмпирически проверенным. Тем не менее именно акцент на ребёнке как «блеске в глазах матери» вызвал волну нового интереса к зеркалированию — как в исследованиях детского развития, так и в клинической ситуации психоанализа и группы.\n\n<p class=\"src\">Источник: Pines, Circular Reflections<\/p>\n**Связанные заметки:** <a class=\"note\" data-note=\"лицо матери как зеркало у Винникотта\">лицо матери как зеркало у Винникотта<\/a>, Клинический пример — феномен зеркала группы\n\n### Продолжение темы: кажущееся отсутствие переноса\n\n→ Аналитику отведено скромное место — условие работы с зеркальным переносом (Кохут)\n→ Кохут, Анализ самости (1971)", "улыбка младенца как рождение связного функционального единства (Шпиц)": "Пайнс обращается к Рене Шпицу, чтобы показать ещё одно применение принципа когерентности — на этот раз через наблюдение за развитием младенца. Шпиц описывает появление улыбки на третьем месяце жизни как поворотный момент психологического развития: устанавливается полярность в терминах принципа удовольствия—неудовольствия, и как будто ряд отдельных функций впервые вступает во взаимосвязь и объединяется в связную единицу. Возникает структурный паттерн, которого раньше не существовало в психике: после этой интеграции реакция на опыт больше не строится из разрозненных, дискретных компонентов, а определяется работой единого целого. С появлением этой связности рождается новый, лучше приспособленный способ функционирования — поведение приобретает более целенаправленный характер, а само это функционирование, принося вознаграждение, закрепляется и продолжает работать.\n\nПайнс приводит и обращение Шпица к эмбриологу Уоддингтону: когда элементы определённой сложности организуются в сущность более высокого уровня, связность этого уровня зависит от свойств, которые изолированные элементы приобретают, вступая в отношения друг с другом — то есть новый уровень организации невозможно вывести из свойств элементов, взятых порознь, но можно понять, если добавить свойства, проявляющиеся только в их сочетании. Пайнс предлагает читать эту мысль применительно к диаде мать—дитя: вместе они и образуют такой новый уровень организации, а путь к этой интеграции изолированных функций прокладывается именно через объектные отношения младенца — через переживания аффективной природы.\n\nПайнс отмечает показательную деталь: в тексте Шпица термин «когезия» встречается лишь однажды и связан с принципом нирваны и гомеостазом — то есть с активностью организма, рассматриваемого изолированно. А термин «когерентность» Шпиц использует именно там, где речь идёт об организации изолированных единиц в более высокий уровень развития — то есть там, где предполагается взаимосвязь младенца и заботящегося взрослого.\n\n<p class=\"src\">Источник: Pines, Circular Reflections<\/p>\n\n**Связанные заметки:** исцеление и излечение, когерентность и связность, биологическое зеркалирование в раннем взаимодействии мать-младенец", "частичные объекты": "Частичный объект — это прежде всего **функция**, а не «предмет»\n\nконцепция бессознательной фантазии\nсодержание бессознательных фантазий всегда в конечном счете можно проследить до мыслей и чувств о функционировании и содержимом собственного тела по отношению к функционированию и содержимому тела другого человека\n\nВ статье _«Заметки о некоторых шизоидных механизмах»_ (1946) Кляйн не даёт формального определения термина _частичный объект_ (как, скажем, в словаре), но чётко и последовательно описывает, **что она имеет в виду под ним**, и как он функционирует в психике младенца.\n\n---\n\n### 📘 **Определение частичного объекта по Кляйн (по статье 1946 г.):**\n\n**Частичный объект** — это **фрагмент объекта, воспринимаемый младенцем не как целое существо, а как функция удовлетворения или фрустрации**, например, «хорошая грудь» или «плохая грудь». Частичные объекты возникают как результат **расщепления** восприятия и фантазии, направленной на управление тревогой.\n\nЧастичный объект:\n\n- **не целостен** (не воспринимается как мать в целом),\n    \n- **заряжен аффектом** (либо исключительно хороший, либо исключительно плохой),\n    \n- **служит контейнером проекции и интроекции**,\n    \n- **формируется в рамках параноидно-шизоидной позиции**.\n    \n\n---\n\n### 📌 Цитата из статьи:\n\n> **«Я часто высказывала мнение, что объектные отношения существуют с самого начала жизни; первым объектом является грудь матери, которая в восприятии ребёнка расщепляется на хорошую (удовлетворяющую) и плохую (фрустрирующую) грудь; это расщепление приводит к разделению любви и ненависти».**\n\n(Раздел _Введение_, в первых абзацах статьи.)\n\n---\n\nЭта цитата показывает:\n\n- объект в начале — **часть тела**, не целое существо;\n    \n- его восприятие **расщеплено**, и это **эмоционально значимо**;\n    \n- именно это восприятие становится **фундаментом ранних объектных отношений**."};
const SITE = new Set(["Безымянный ужас — непринятое возвращается (Бион, 1962)", "Жадность, зависть и благодарность (Кляйн, 1957)", "Искусство как репарация (Сегал, 1952)", "Использование объекта — другой реален, если пережил разрушение (Винникотт, 1969)", "Ложное творение — перверсия как подделка творчества (Шассге-Смиргель, 1984)", "Луиза Буржуа — искусство как гарантия душевного здоровья", "Перенос — промежуточное царство между болезнью и жизнью (Фрейд, 1914)", "Писатель и фантазирование — эстетическая премия (Фрейд, 1908)", "Призраки становятся предками (Лёвальд, 1960)", "Регрессия на службе Я (Крис, 1952)", "Символическое уравнение — символ и вещь совпадают (Сегал, 1957)", "Страх распада — катастрофа, которая уже случилась (Винникотт, 1974)", "Таласса — тяга вернуться в материнское лоно (Ференци, 1924)", "Частичный и целый объект — путь к депрессивной позиции (Кляйн)"]);
const css = `
a.note { text-decoration: none; cursor: pointer; transition: color .2s; }
a.note::after { content: '°'; display: inline-block; font-family: 'Lora', serif; font-style: normal; font-weight: 600; font-size: .62em; line-height: 1; vertical-align: super; color: #E3A781; margin-left: .12em; transition: transform .2s; }
a.note:hover, a.note:focus-visible { color: #E3A781; outline: none; }
a.note:hover::after { transform: scale(1.35); }
#overlay { position: fixed; inset: 0; background: rgba(8,6,5,0.55); opacity: 0; pointer-events: none; transition: opacity .35s; z-index: 60; }
#overlay.open { opacity: 1; pointer-events: auto; }
#drawer { --paper: #EEE4D1; --ink: #2A211C; --ink-soft: #4B3F37; --ink-muted: #6B5C51; --rust: #9A4528; position: fixed; top: 0; right: 0; height: 100%; width: min(600px, 100vw); background: var(--paper); color: var(--ink); z-index: 70; transform: translateX(102%); transition: transform .45s cubic-bezier(.2,.7,.2,1); display: flex; flex-direction: column; box-shadow: -20px 0 60px rgba(0,0,0,0.45); font-family: 'Lora', Georgia, serif; text-align: left; }
#drawer.open { transform: none; }
#drawer header { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 14px 18px; border-bottom: 1px solid #D8C9B0; }
#drawer header .lbl { font-family: 'Caveat', cursive; font-size: 24px; color: var(--rust); }
#drawer header .btns { display: flex; gap: 6px; }
#drawer header button { background: none; border: 1px solid #D8C9B0; border-radius: 50%; width: 38px; height: 38px; cursor: pointer; color: var(--ink); font-size: 18px; }
#drawer header button:hover { background: #E4D7BE; }
#drawer header button[hidden] { display: none; }
#drawer .body { overflow-y: auto; padding: 22px 30px 60px; -webkit-overflow-scrolling: touch; }
#drawer h2.ntitle { font-family: 'Cormorant Garamond', Georgia, serif; font-size: 32px; line-height: 1.15; font-weight: 600; margin: 0 0 18px; color: var(--ink); }
#drawer .md { font-size: 17px; line-height: 1.7; color: var(--ink-soft); }
#drawer .md p, #drawer .md ul, #drawer .md ol, #drawer .md blockquote { margin: 0 0 1em; }
#drawer .md h1, #drawer .md h2, #drawer .md h3, #drawer .md h4 { font-family: 'Cormorant Garamond', Georgia, serif; color: var(--ink); line-height: 1.2; margin: 1.3em 0 .5em; }
#drawer .md h1 { font-size: 30px; } #drawer .md h2 { font-size: 27px; } #drawer .md h3 { font-size: 23px; } #drawer .md h4 { font-size: 20px; }
#drawer .md strong { color: var(--ink); }
#drawer .md blockquote { border-left: 3px solid var(--rust); padding-left: 14px; font-style: italic; }
#drawer .md mark { background: #EBCFB8; color: inherit; padding: 0 2px; }
#drawer .md .src { font-size: 14px; color: var(--ink-muted); font-style: italic; }
#drawer .md table { border-collapse: collapse; font-size: 15px; margin: 0 0 1em; }
#drawer .md th, #drawer .md td { border: 1px solid #D8C9B0; padding: 6px 8px; text-align: left; }
#drawer a.note { text-decoration: underline; text-decoration-color: rgba(154,69,40,.45); text-underline-offset: .15em; }
#drawer a.note::after { color: var(--rust); }
#drawer a.note:hover { color: var(--rust); }
@media (max-width: 760px) { #drawer .body { padding: 18px 20px 60px; } }
`;
const st = document.createElement('style'); st.textContent = css; document.head.appendChild(st);
const overlay = document.createElement('div'); overlay.id = 'overlay';
const drawer = document.createElement('aside'); drawer.id = 'drawer'; drawer.setAttribute('aria-hidden', 'true'); drawer.setAttribute('aria-label', 'Заметка');
drawer.innerHTML = '<header><span class="lbl"></span><span class="btns"><button class="back" title="Назад" hidden>←</button><button class="close" title="Закрыть">✕</button></span></header><div class="body"></div>';
document.body.append(overlay, drawer);
const body = drawer.querySelector('.body'), backBtn = drawer.querySelector('.back'), lbl = drawer.querySelector('.lbl');
const md = s => window.marked ? marked.parse(s) : '<p>' + s.replace(/\n\n/g, '</p><p>') + '</p>';
let stack = [];
function render(name) {
  const n = NOTES[name]; if (n === undefined) return;
  lbl.textContent = SITE.has(name) ? 'заметка к статье' : 'заметка из рабочей базы';
  body.innerHTML = '<h2 class="ntitle"></h2><div class="md"></div>';
  body.querySelector('.ntitle').textContent = name;
  body.querySelector('.md').innerHTML = md(n);
  body.scrollTop = 0;
  backBtn.hidden = stack.length < 2;
}
function openNote(name) {
  if (NOTES[name] === undefined) return;
  stack.push(name); render(name);
  drawer.classList.add('open'); overlay.classList.add('open'); drawer.setAttribute('aria-hidden', 'false');
}
function closeNote() { drawer.classList.remove('open'); overlay.classList.remove('open'); drawer.setAttribute('aria-hidden', 'true'); stack = []; }
document.addEventListener('click', e => {
  const a = e.target.closest('a.note'); if (!a) return;
  e.preventDefault(); e.stopPropagation(); openNote(a.dataset.note);
}, true);
document.querySelectorAll('a.note').forEach(a => { a.setAttribute('href', '#'); a.setAttribute('role', 'button'); });
overlay.addEventListener('click', closeNote);
drawer.querySelector('.close').addEventListener('click', closeNote);
backBtn.addEventListener('click', () => { stack.pop(); render(stack[stack.length - 1]); });
addEventListener('keydown', e => { if (e.key === 'Escape' && drawer.classList.contains('open')) { e.stopPropagation(); closeNote(); } }, true);
window.NOTES_UI = { openNote, closeNote, isOpen: () => drawer.classList.contains('open') };
})();
